COLLDATA("sh11237","ar",[[1,"وسمعته يقول: هشيم عن إسماعيل بن سالم كوفي ثقة. أيوب"],[2,"سمعته يقول: أيوب بن ياسر مديني كان بفيد، متروك روى عن سهيل وسمى وهشام(1).","",{"fn":"(1) قال فيه مرة، منكر الحديث، الضعفاء رقم الترجمة ١٠٧"}],[3,"وأيوب بن عتبة عن يحي بن أبي كثير هو يمامي يترك. وقال مرة أخرى يعتبر به شيخ(1) قيل له.","",{"fn":"(1) تهذيب التهذيب ١/٤٠٩"}],[4,"مثل أيوب بن جابر(1) قال: لا. هذا قوي، يعني أيوب بن عتبة أقوى.","",{"fn":"(1) السحيمي بمهملتين مصغرا ضعيف من السابعة تقريب التهذيب ٤١."}],[5,"أيوب بن هانئ عن أبيه. هو كوفي يعتبر به، وسمعته يقول مرة أخرى ابن هانئ الذي حدث عنه ابن جريج يعتبر به(1).","",{"fn":"(1) تهذيب التهذيب /٤١٤"}],[6,"وأيوب بن واقد عن أبي ليلى بصري متروك(1).","",{"fn":"(1) قال فيه مرة مقل كوفي الضعفاء رقم الترجمة ١٠٩."}],[7,"وأيوب أبو العلاء القصاب هو ابن أبي مسكين وقيل ابن مسكين شيخ من أهل واسط يعتبر به."],[8,"وأيوب بن وايل يحدث عن نافع حدث عنه حماد بن زيد وهو مقل من أهل البصرة، صاحب حديث لا بأس به(1). إبراهيم","",{"fn":"(1) قال الذهبي له حديث واحد في الكامل وقال البخاري حديثه في البصريين ولم يتابع عليه التاريخ الكبير ١/١/٤٢٥. ميزان الاعتدال /٢٩٥."}],[9,"سمعته يقول إبراهيم بن إسحاق الصيني متروك(1).","",{"fn":"(1) انظر نص الكلام في الضعفاء رقم الترجمة ١٠."}],[10,"وإبراهيم بن هراسه متروك لا يخرج حديث(1).","",{"fn":"(1) قال مرة: روى عن الزهري حديثا لم يتابع عليه الضعفاء رقم الترجمة ٣٠."}],[11,"وإبراهيم بن إسماعيل بن مجمع متروك."],[12,"وإبراهيم بن إسماعيل بن أبي حبيبة متروك."],[13,"وإبراهيم بن بكر الشيباني بغدادي متروك."],[14,"وإبراهيم بن نافع من أهل مكة لا بأس به."],[15,"وإبراهيم بن نشيط(1) الوعلاني يحدث عنه ابن وهب مدني يقة. إسحاق","",{"fn":"(1) قال الحافظ: إبراهيم بن نشيط بفتح النون وكسر المعجمة الوعلاني بالمهملة البصري يكنى أبا بكر ثقة من الخامسة تقريب التهذيب ٢٤."}],[16,"وسمعته يقول إسحاق بن أبي إسحاق الشيباني يحدث عن أبيه ثقة كوفي."],[17,"وإسحاق بن زيد الهذلي يحدث عنه ابن أبي ذئب مديني لا بأس به."],[18,"وإسحاق بن عمر عن عائشة، مجهول يترك(1).","",{"fn":"(1) انظر الضعفاء رقم الترجمة: ١٠٠"}],[19,"وإسحاق بن إبراهيم أبو النضر الدمشقي ثقة يحدث عنه فهد بن سليمان، قال البرقاني(1) رحمه الله، الذي في التعليق عندنا بن زيد أبو النضر الدمشقي(2). أحمد","",{"fn":"(1) البرقاني: بفتح الباء الموحدة وسكون الراء المهملة وفتح القاف- اللباب ١/١٤٠.\n(2) هما واحد واسمه الكامل إسحاق بن إبراهيم بن يزيد أبو النضر الدمشقي وربما نسب إلى جده كما في التهذيب. قال الحافظ ابن حجر: صدوق ضعف بلا مستند تقريب التهذيب٢٧ تهذيب التهذيب ١/٢١٩."}],[20,"سمعته يقول أحمد بن خالد الوهبي لا بأس به."],[21,"وأحمد بن عبد الوهاب بن نجدة حمصي يحدث عن أبيه لا بأس بهما."],[22,"وأحمد بن عبد الله الفربناني(1) مروزي متروك.","",{"fn":"(1) قال ابن الأثير الفرياناني بكسر الفاء وسكون الراء وفتح الياء آخر الحروف وسكون الألف بينهما نون مفتوحة وفي آخرها ثانية نسبة إلى فريانان قرية عند مرو اللباب ٢/٤٢٧."}],[23,"وأحمد بن عبد الله الجويباري هروي متروك. وسمعته يقول:"],[24,"أحوص بن حكيم بن عمير العنسي حمصي يعتبر به إذا حدث عنه ثقة١."],[25,"أيمن بن عبيد بن أم أيمن أخو أسامة بن زيد لأمه قتل في عهد النبي صلى الله عليه وسلم."],[26,"وأصبغ بن زيد الوراق واسطي ثقة عندي يروي عن ثور بن زيد وقد تكلم فيه(1).","",{"fn":"(1) قال فيه مرة: منكر الحديث الضعفاء رقم الترجمة: ١٢٠."}],[27,"وأسيد بن أبي أسيد(1) البراد مدني يعتبر به.","",{"fn":"(1) أسيد بمفتوحة فمكسورة فتحتية المغتي ٢١."}],[28,"إياس بن صبيح هو أبو مريم الجعني بصري تابعي ثقة(1).","",{"fn":"(1) ذكره ابن أبي حاتم وسكت عنه الجرح والتعديل ١/١/٢٨٠."}],[29,"وأشعث بن بنت دجاجة، قال من أهل الكوفة صالح ويقال له فليت."],[30,"وسمعته يقول: عطاء عن أيمن ليس بصحابي هو والد عبد الواحد، عن النبي صلى الله عليه وسلم مرسل."],[31,"وسمعته يقول: أسد بن عمرو البجلي يعتبر به."],[32,"وقلت له: أشعث عن الحسن، فقال: هم ثلاثة يحدثون جميعا عن الحسن أحدهم الحمراني المنسوب إلى حمران مولى عثمان، بصري وهو أشعث بن عبد الملك أبو هاني ثقة."],[33,"وأشعث بن عبد الله الحداني بصري أيضا يروي عن أنس والحسن يعتبر به."],[34,"وأشعث بن سوار الكوفي يعتبر به وهو أضعفهم روى عنه شعبة حديثا واحدا. في حرف الباء"],[35,"قلت لأبي الحسن روى حرب بن شداد عن يحي بن أبي كثير عن باب عن ابن عمير عن رجل عن أبيه عن أبي هريرة؟. قال.... باب لا أدري من هو يحدث عنه الأوزاعي ويحي ويترك هذا الحديث(1).","",{"fn":"(1) قال ابن أبي حاتم: باب بن عمير الحنفي الشامي ولم يذكر فيه شيئا الجرح والتعديل ١/١/٤٣٩. وذكره الدارقطني في كتاب الضعفاء وقال فيه مجهول، الضعفاء رقم الترجمة: ١٣٣"}],[36,"وسمعته يقول: بدر بن عثمان كوفي ثقة."],[37,"وبدر بن خليل الأسدي كوفي روى عنه شريك لا بأس به."],[38,"وسمعته يقول: بركة بن يعلى عن أبي سويد العبدي عن ابن عمر مجهولان(1).","",{"fn":"(1) انظر الضعفاء رقم الترجمة: ١٣٣"}],[39,"وسمعته يقول بسطام بن عبد الوهاب عن مكحول مجهول(1).","",{"fn":"(1) ميزان الاعتدال ١/٣٠٩"}],[40,"سألته عن بشر بن عمارة الخثعمي فقال: متروك."],[41,"وعن بشر بن السري، فقال: ثقة مكي(1).","",{"fn":"(1) قال الحافظ: طعن فيه برأي جهم ثم اعتذر وتاب تقريب التهذيب ٤٤."}],[42,"وسألته عن بشير بن ميمون عن مجاهد فقال: أو صيفي واسطي متروك."],[43,"وسألته عن بشير بن سليمان فقال: أبو إسماعيل كوفي لا بأس به."],[44,"قلت له: روى بركة عن بشير بن نهيك، فقال بركة شيخ للبصريين يعتبر به."],[45,"وبشير بصري ثقة."],[46,"وسمعته يقول: بكر بن عبد الرحمن بن عبد الله بن عيسى بن عبد الرحمن ابن أبي ليلبى: قاضي الكوفة ثقة(1).","",{"fn":"(1) قال الحافظ: ويقال له بكر بن عبيد تقريب التهذيب ٤٧."}],[47,"وبكر بن عمرو المعافا(1) بصري يعتبر به.","",{"fn":"(1) هكذا في النسخة وفي الميزان والتقريب المعافري. ميزان الاعتدال ١/٣٤٧ تقريب التهذيب ٤٧."}],[48,"وبكر بن خنيس: متروك كان ببغداد(1).","",{"fn":"(1) بكر بن خنيس بالمعجمة والنون آخره سين مهملة، وقد ذكره الدارقطني في الضعفاء ولم يذكر فيه جرحا، ويفهم من كلام البرقاني هناك أنه متروك الضعفاء رقم الترجمة: ١٢٦، تقريب التهذيب ٤٧."}],[49,"وبكر بن وايل بن داود كوفي ثقة ثقة، يروي أبوه عنه."],[50,"وسمعته يقول: معتمر عن بيان أبي سهيل الرقاشي عن أنس، يقول البخاري هو الذي يحدث عنه شعبة ويكنيه أبا صدقة، وقال غيره صاحب شعبة اسمه سليمان بن كندير أبو صدقة(1).","",{"fn":"(1) التاريخ الكبير: ٢/١/٣٣."}],[51,"سألته عن زريع بن حسان، فقال: أبو الخليل بصري متروك. قلت له: عن هشام بن عروة عجايب، قال هي بواطيل، ثم قال كل شيء له باطل. في حرف التاء والثاء سمعت أبا الحسن الدارقطني رحمه الله يقول:"],[52,"تميمة بنت سلمة عن عائشة لا بأس بها."],[53,"ثابت بن عمارة بصري ثقة."],[54,"ثابت بن أبي صفية أبو حمزة الثمالي(1) متروك.","",{"fn":"(1) الثمالي بضم المثلثة واسم أبيه دينار وقيل سعيد كوفي ضعيف رافضي الضعفاء رقم الترجمة: ١٣٧، وميزان الاعتدال ١/٣٦٣. تقريب التهذيب ٥٠."}],[55,"ثمامة بن شراحبيل عن ابن عمر من أهل صنعاء لا بأس به(1) شيخ مقل.","",{"fn":"(1) قال الحافظ: مقبول من الثالثة تقريب التهذيب ٥٣."}],[56,"ثوير بن أبي فاختة مولى بني هاشم متروك، وأبو فاختة سعيد ابن علاقة(1). في حرف الجيم سألت أبا الحسن علي بن عمر عن:","",{"fn":"(1) ذكره في الضعفاء وقال: نوير بن أبي فاختة ضعيف، مولى بني هاشم واسم أبيه سعيد بن علاقة كوفي ثقة رقم الترجمة ١٣٨."}],[57,"الجراح أبي وكيع، فقال ليس بشيء هو كثير الوهم، قلت يعتبر به، قال: لا."],[58,"وسألته عن الجلاح أبي كثير فقال لا بأس به مصري(1).","",{"fn":"(1) الجرح والتعديل ١/١/٥٥١."}],[59,"وسألته عن جسرة بنت دجاجة، فقال: يعتبر بحديثها إلا أن بحدث عنها من يترك."],[60,"وسألته عن جسر بن فرقد فقال متروك."],[61,"وسألته عن جبارة بن مغلس فقال متروك."],[62,"قلت له، جميل بن حماد عن عصمة بن زامل عن أبيه عن أبي هريرة ... فقال هذا إسناد بدوي يخرج اعتبارا(1).","",{"fn":"(1) ذكره الحافظ بنصه ولم يزد على ما أورده البرقاني لسان الميزان ٢/١٣٦."}],[63,"قلت فجميل بن عبيد الطائي، قال هو بصري يعتبر به."],[64,"سألته عن الجارود بن أبي سبرة(1) والد ربعي فقال بصري ثقة.","",{"fn":"(1) قال الحافظ: ابن أبي سبرة بفتح المهملة وسكون الموحدة تهذيب التهذيب ٥٣."}],[65,"وسألته عن جعفر بن برد(1) عن مولاته أم سالم الدوسية عن عائشة فقال يترك الحديث، وليس يروي عن أم سالم غير جعفر هذا وهو شيخ بصري مقل يعتبر به.","",{"fn":"(1) برد يضم الموحدة وسكون الراء تهذيب التهذيب ٥٥."}],[66,"قلنا له جعفر بن عمران يحدث عنه أحمد بن يونس فقال لا أعرفه."],[67,"قلت: جعفر بن أحمد بن عمران يحدث عنه الطلحي، فقال كوفي ثقة حدث عنه الناس قديما."],[68,"قلت: جعفر بن ميمون فقال بصري يحدث عنه الثوري وغيره يعتبر به."],[69,"قلت له: فجعفر بن زياد الأحمر. فقال كوفي يعتبر به."],[70,"قلت جعفر بنأبي الحسن الخواري(1) يحدث عن غنام(2) عنه قال متروك.","",{"fn":"(1) الخواري بضم الخاء وفتح الواو وبعد الألف راء.. اللباب ١/٤٦٧.\n(2) في الضعفاء للدارقطني أبو غنام، وفي الميزان واللسان ابن غنام الضعفاء للدارقطني رقم الترجمة: ١٤٧.، ميزان الاعتدال ١/٤٠٥، لسان الميزان ٢/١١٤."}],[71,"قلت له: وأبو الحسن بن المظفر حاضر، جعفر بن برقان، فقالا جميعا، قال أحمد بن حنبل يؤخذ من حديثه ما كان عن غير الزهري فأما عنه فلا، قلت فقد لقيه فما بلاؤه، قال الدراقطني: ربما حدث عن الثقة عن ابن برقان عن الزهري ويحدثه الآخر عن ابن برقان عن رجل عن الزهري أويقول بلغني عن الزهري فأما حديثه عن ميمون ابن مهران ويزيد بن الأصم فثابت صحيح(1). في حرف الحاء قلت لأبي الحسن:","",{"fn":"(1) قال المزي قال البرقاني عن الدارقطني: ربما حدث الثقة عن ابن برقان عن الزهري ويحدث الآخر بذلك الحديث عن ابن برقان عن الزهري أو يقول بلغني عن الزهري. قلت: والكلام الذي في الأصل أقوم مما نقله المزي، تهذيب الكمال ١/٩٨.تهذيب التهذيب ٢/٨٥."}],[72,"أبو المليح الرقى الحسن بن عمر، فقال ابن عمر وقيل ابن عمرو والأول هو الصواب ثقة."],[73,"وسألته عن الحسن بن يزيد الأصم صاحب السدي. قال كوفي لا بأس به. ثقة مستقيم الحديث(1).","",{"fn":"(1) قال الحافظ: صدوق يهم من الثامنة، تقريب التهذيب ٧٣."}],[74,"قلت له الحسن بن شبيب المؤدب. فقال أخباري يعتبر به وليس بالقوي يحدث عنه المحاملي(1).","",{"fn":"(1) قال ابن عدي: حدث عن الثقات بالبواطيل وأوصل أحاديث هي مرسلة، وقال الذهبي: المتعين ما قال ابن عدي فيه، الكامل: ١/٢/١٢٣، ميزان الاعتدال ١/٤٩٥."}],[75,"قلت له: الحسين بن زيد بن علي بن الحسين(1) عن عبد الله بن محمد ابن عمر بن علي عن أبيه عن جده عن علي. فقال كلهم ثقات.","",{"fn":"(1) قال الحافظ: صدوق ربما أخطأ تقريب التهذيب ٧٣"}],[76,"قلت له. الحسين بن محمد بن شنبه(1) يحدث عنه المقانعي والقتات، فقال واسطي صالح.","",{"fn":"(1) شنبه: بفتح المعجمة والنون الموحدة تقريب التهذيب ٧٥."}],[77,"سألته عن الحسين بن عبد الله بن ضميره فقال متروك(1) لا يحدث إلا عن أبيه عن جده.","",{"fn":"(1) ذكره في الضعفاء وقال: مدني رقم الترجمة: ١٨٩."}],[78,"وعن الحسن بن زياد اللؤلؤي فقال كوفي متروك(1).","",{"fn":"(1) قال الذهبي: قال الدارقطني ضعيفمتروك، ميزان الاعتدال ١/ ٤٩١ قلت: وذكره في الضعفاء رقم الترجمة: ١٨٥"}],[79,"سألته عن حبيب بن أبي مرزوق يحدث عنه جعفر بن برقان فقال هو جزري ثقة يحتج به."],[80,"قلت له حبيب عن أنس: فقال هذا حبيب الإسكاف أبو عميرة كوفي متروك(1).","",{"fn":"(1) سكت عنه في الضعفاء رقم الترجمة: ١٧٠."}],[81,"قلت له حبيب بن أبي حبيب يروي عن عبد الرحمن بن القاسم فقال شيخ بصري يعتبر به(1).","",{"fn":"(1) في اللسان ٢/١٧٠ بصري لا يعتبر به."}],[82,"قلت حميد بن حماد بن خوار، فقال وقيل ابن أبي الخوار(1) من أهل الموفة يعتبر به.","",{"fn":"(1) قال الحافظ: ابن خوار بضم المعجمة وتخفيف الواو تقريب التهذيب ٨٤."}],[83,"قلت حميد بن صخر أبو صخر. فقال هو حميد بن زياد مدني، ولكن كذا يقال. وهو ثقة."],[84,"قلت فحميد بن علي العقيلي فقال لا يستقيم حديثه. لا يحتج به."],[85,"قلت فحميد بن هانئ أبو هاني قال مصري لا بأس به. ثم قال ثقة."],[86,"قلت فحميد مولى(1) علقمة عن عطاء. قال مجهول.","",{"fn":"(1) قال الحافظ: مولى ابن علقمة مجهول تقريب التهذيب ٨٥."}],[87,"قلت حميد بن عطاء. عن عبد الله بن الحارث ابن مسعود، فقال: حميد متروك، أحاديثه شبه الموضوعة وهو كوفي، وعبد الله بن الحارث كوفي ثقة ولم يسمع من ابن مسعود(1).","",{"fn":"(1) انظر ما ذكره الحافظ في تهذيب التهذيب ٣/٥٣"}],[88,"وسألته عن الحكم بن عبد الله الأيلي(1) صاحب القاسم بن محمد فقال متروك.","",{"fn":"(1) ذكره في الضعفاء وجعله في نفس هذه الدرجة رقم الترجمة: ١٥٩."}],[89,"وسمعته يقول الحكم بن مينا(1) من أهل المدينة ثقة.","",{"fn":"(1) الحكم بن ميناء: بكسر الميم بعدها التحتانية ثم نون ومد، تقريب التهذيب ٨٠."}],[90,"وسألته عن حكيم بن جبير فقال كوفي يترك، هو الذي روى \"لا تحل الصدقة لمن له خمسون درهما(1)\" ٤.","",{"fn":"(1) رواه الترمذي وقال حديث حسن وقد تكلم شعبة في حكيم بن جبير من أجل هذا الحديث، وفي الباب عن عبد الله بن عمرو. ورواه النسائي وابن ماجة في كتاب الزكاة. تحفة الأحوذي ٣/٣١٤، سنن النسائي ٥/٩٧، سنن ابن ماجة ١/٥٨٩."}],[91,"قلت له: الحارث بن حجاج عم أبي الحجاج عن أبي معمر عن سالم ابن عبد الله، فقال مجهولان."],[92,"قلت: معن عن الحارث بن عبد الله الليثي فقال مدني صالح."],[93,"قلت الحارث بن عمران، قال: أبو سهل الجعفري كوفي متروك."],[94,"وسمعته يقول: الحارث بن حصيرة(1) شيخ للشيعة يغلو في التشيع.","",{"fn":"(1) ابن حصيرة بكسر الصاد.الخلاصة ٦٧."}],[95,"وسمعته يقول الحارث بن عمير أبو عمير، بصري سكن مكة، وهو ثقة(1).","",{"fn":"(1) نقل الحافظ في ترجمته نقولا متضاربة، وارى أن ما توصل إليه في التقريب أدق مما ذكره الإمام الدارقطني تهذيب التهذيب ٢/١٥٣ تقريب التهذيب ٦٠."}],[96,"وسمعته يقول حجاج بن أبي عثمان الصواف، يكنى أبا الصلت بصري ثقة يروي عن أبي الزبير ويحي بن ابي كثير."],[97,"وحجاج بن أبي زينب يكنى أبا يوسف واسطي يروي عن أبي عثمان وعن أبي سفيان طلحة بن نافع، يروي عنه الواسطيون، ثقة(1)","",{"fn":"(1) قال الحافظ: قال الدارقطني ليس بالقوي ولا حافظ، وقال في موضع آخر ثقة، تهذيب التهذيب ٢/٢٠١."}],[98,"وحجاج بن أرطأة أبو أرطأه كوفي."],[99,"وسألته عن حرب بن سريج(1) يحدث عنه طالوت بن عباد، فقال.. المقري. بصري صالح. وأخوه بشر بن سريج صالح.","",{"fn":"(1) ابن سريج بالمهملة والجيم، تقريب التهذيب ٦٦."}],[100,"سالته عن حيان بن علي وأخيه مندل، فقال متروكان، وقال مرة أخرى ضعيفان(1) ويخرج حديثهما(2).","",{"fn":"(1) ذكره في الضعفاء رقم الترجمة: ٧٣، بدون ذكر ما بعده.\n(2) ذكره المزي نقلا عن الدارقطني تهذيب الكمال ٢/١١٤ ب."}],[101,"وسمعته يقول الحريش بن الخريت(1) أخو الزبير بن الخريت يعتبر به وهما بصريان والزبير ثقة.","",{"fn":"(1) حريش بوزن حريز ابن الخريت بكسر المعجمة وتشديد الراء المكسورة وآخرة مثناة تقريب التهذيب"}],[102,"قلت له حابس اليماني عن أبي بكر الصديق، فقال مجهول متروك(1) قلت له عن أبي ذر، فقال لايثبت مصري يترك.","",{"fn":"(1) ذكر المزي وابن حجر كلاما كثيرا حول هذه الترجمة، تهذيب الكمال ٢/١٠٦. تهذيب التهذيب ٢/١٢٧."}],[103,"قلت له: أبو شهاب عن حمزة فقال هو حمزة النصيبي يحدث عن عمرو وغيره متروك."],[104,"قلت له: أبو العلاء بن الشخير عن الحنظلي عن شداد، فقال أبو العلاء اسمه يزيد أخو مطرف، والحنظلي مجهول لا يسمى، يترك هذا الحديث."],[105,"وسمعته يقول: أبو غالب اسمه حزور(1) بصري لا يعتبر به(2) وقلت له مرة أخرى أبو غالب عن أبي أمامة فقال بصري واسمه حزور، قلت ثقة قال نعم.","",{"fn":"(1) حزور بفتح أوله والزاي وتشديد الواو وآخره راء تهذيب التهذيب ٦٧.\n(2) في تهذيب التهذيب: قال البرقاني عن الدارقطني أبو غالب حزور بصري يعتبر به. قلت: ولعل هذا هو الأصوب ليوافق توثيق الدارقطني له، وانظر تهذيب التهذيب ١٢/١٩٨."}],[106,"وسمعته يقول حزم بن أبي حزم القطعي ثقة."],[107,"قلت له حصن٣ عن أبي سلمة ب(1)ن عبد الرحمن فقال يحدث عنه الأوزاعي يعتبر به(2).","",{"fn":"(1) حصن: بكسر ثم مهملة ساكنة ثم نون تقريب التهذيب ٧٦.\n(2) في تهذيب الكمال: قال الدارقطني شيخ يعتبر به، تهذيب الكمال ٢/١٥٠."}],[108,"قلت: فحصين بن نافع المازني، فقال بصري روى عن الحسن حديثين أو ثلاثة ليس به بأس."],[109,"سألته عن حصين بن جندب أبي ظبيان فقال: ثقة."],[110,"سألته عن حفص بن عمر القناد(1) فقال: هو من ناحية العسكر متروك، يحدث عته عبد الله بن رشيد وهو يحدث عن عبد الله بن عمر.","",{"fn":"(1) القناد: بفتح القاف والنون، وقد أورد الحافظ الذهبي ونقل فيه قول الدارقطني، الأنساب للسمعاني ١٠/٤٨٨، ميزان الاعتدال ١/٥٦٦."}],[111,"سألته عن حفص بن عمر الحلبي، فقال اجعله كوفي، ثم ولي قضاء حلب، صالح يعتبر به(1).","",{"fn":"(1) ضعفه أبو حاتم وقال أبو زرعة منكر الحديث، وقال ابن حبان يروي عن الثقات الموضوعات لا يحل الاحتجاج به. الجرح والتعديل ١/٢/١٧٩، المجروحين ١/٢٥٩، لسان الميزان ٢/٣٢٦."}],[112,"وعن الحسام بن مصك(1) فقال بصري يعتبر به.","",{"fn":"(1) ابن مصك: بكسر الميم وفتح المهملة بعدها كاف مثقلة تقريب التهذيب ٦٧."}],[113,"سألته عن حفصة بنت عازب فقال: هي بنت عبيد بن عازب عن البراء لا يكاد يحدث عنها غير ابن أبي ليلى يخرج حديثها."],[114,"قلت له: حفص عن أنس هو ابن أخي أنس، قال نعم، هو حفص ابن عمر بن عبد الله بن أبي طلحة، قلت ثقة قال نعم. في حرف الخاء"],[115,"سمعته يقول: خصيف(1) بن عبد الرحمن جزري يعتبر به. يهم.","",{"fn":"(1) بالصاد المهملة مصغرا وقد ذكر في التقريب تحت خصيب وفي تهذيب التهذيب خصيف، تقريب التهذيب ٩٢، تهذيب التهذيب ٣/١٤٣."}],[116,"وسمعته يقول: خازم بن الحسين أبو إسحاق الحميس(1) بصري وقع إلى الكوفة في آخر أمره، متروك يحدث عن مالك بن دينار وغيره.","",{"fn":"(1) الحميس بضم الحاء المهملة وفتح الجيم هكذا ضبطه السمعاني، وفي التقريب الخميس بفتح المعجمة، الأنساب ٢/٣٦٦، تقريب التهذيب ٨٧."}],[117,"قلت له أحمد بن يونس عن الخزرج(1) بن عثمان عن أبي أيوب عن أبي هريرة....جماعة ولكن هذا مجهول.","",{"fn":"(1) الخزرج: بفتح أوله وسكون الزاي وفتح الراء بعدها جيم تقريب التهذيب ٩٢."}],[118,"قلت له: خليد بن دعلج، ثقة قال: لا."],[119,"قلت: عطاء الخرساني عن خليد السلامي(1) عن أم الدرداء فقال: مجهول ثقة(2).","",{"fn":"(1) في الميزان واللسان، وسلامان من قضاعة. ميزان الاعتدال ١/٦٦٤، لسان الميزان ٢/٤٠٦.\n(2) هكذا في النسخة وفي اللسان: قال الدارقطني مجهول يترك، قلت: هذا أصوب لأن المجهول محال أن يكون ثقة، لسان الميزان ٢/٤٠٦."}],[120,"قلت: خلف بن عقبة عن أبي الزهراء خادم أنس بن مالك فقال: خلف بصري وأبو الزهراء مجهول."],[121,"سألته عن خلف بن محمد بن عيسى، فقال: أبو الحسين يعرف بكردوس(1) واسطي ثقة.","",{"fn":"(1) كردوس يضم الكاف تقريب التهذيب ٩٣."}],[122,"سألته عن خالد بن حسان يروي عنه ابن نمير فقال: هو أبو يزيد الخراز لا بأس به."],[123,"وسألته عن خالد بن مشكان، الفراء فقال: البصري مقل يعتبر به."],[124,"وسألته عن خالد بن يزيد بن صالح بن صبيح المري، فقال: والد عراك، هو دمشقي يعتبر به."],[125,"وعن الخصيب بن زيد يروي عن الحسن فقال: شيخ لا بأس به، ليس له كبير مسند. في حرف الدال"],[126,"سمعته يقول: داود بن بكر بن أبي الفرات ويقال داود بن أبي الفرات مدني يعتبر به."],[127,"وداود بن عطاء من أهل مكة(1) متروك.","",{"fn":"(1) قال ابن حبان: من أهل المدينة، وصوب الحافظ ابن حجر ما قاله الدارقطني، المجروحين ١/٨٩، تهذيب التهذيب ٣/١٩٤."}],[128,"وداود الطفاوي بصري يترك."],[129,".وداود الطائي هو ابن نصير(1)","",{"fn":"(1) ابن نصير بضم النون ثقة فقيه زاهد من الثامنة –س- تقريب التهذيب ٩٧."}],[130,"وداود بن أبي عاصم بن مسعود القفي طايفي محتج به."],[131,"وسمعته يقول دراج(1) أبو السمح هو ابن سمعان مصري متروك.","",{"fn":"(1) دراج بتثقيل الراء وآخره جيم، أبو السمح بمهملتين الأولى مفتوحة والميم ساكنة تقريب التهذيب ٩٧."}],[132,"قلت له: أبو سعيد عن علي قال: هو عقيصا واسمه دينار متروك."],[133,"وسألته عن داهر بن نوح، فقال لا بأس به(1).","",{"fn":"(1) قال في العلل: شيخ للأهواز ليس بقوي لسان الميزان ٢/٤١٣."}],[134,"وعن دلهم بن صالح، فقال: كان بالكوفة صالح. في حرف الذال"],[135,"سألته عن ذي مخبر(1) صاحب النبي صلى الله عليه وسلم فقال: هو ابن أخي النجاشي. في حرف الراء","",{"fn":"(1) ذو مخبر: بكسر أوله وسكون المعجمة وفتح الموحدة وقيل: بدلها ميم، تقريب التهذيب ٩٩."}],[136,"سمعته يقول: روح بن غطيف متروك."],[137,"ورفدة٦ بن قضاعة متر(1)وك.","",{"fn":"(1) رفده: بكسر الواو وسكون الفاء- ووقع في التقريب، رفعه ولعله تحريف وقد ورد على الصواب في تهذيب التهذيب."}],[138,"وأبو عصام رواد(1) بن الجراح العسقلاني متروك.","",{"fn":"(1) رواد بتشديد الواو صدوق اختلط في آخره فترك تقريب التهذيب ١٠٤."}],[139,"وسمعته يقول: رجاء بن أبي رجاء مجهول، يروي عن مجاهد، وقيل هو رجاء بن الحارث."],[140,"وسمعته يقول: ريحان بن سعيد بصري يحتج به."],[141,"وسمعته يقول: ربعي(1) بن الجارود بن أبي بصرة. بصري لا بأس به.","",{"fn":"(1) بعي: بكسر أوله وسكون الموحدة تقريب التهذيب ١٠٠."}],[142,"وسمعته يقول: ربيعة بن سيف المعافري مصري صالح."],[143,"وربيع بن زيد الدمشقي يعرف بالقصير، يعتبر به."],[144,"وربيه الجرشي(1) يروي عنه ابن معدان. ثقة.","",{"fn":"(1) الجرشي: بضم الجيم وفتح الراء بعدها معجمة، مختلف في صحبته وكان فقيها وثقه الدارقطني، تقريب التهذيب ١٠٢"}],[145,"والربيع بن يحي الأشناني (1) ضعيف ليس بالقوي يخطئ كثيرا.","",{"fn":"(1) بضم الألف وسكون المعجمة تقريب التهذيب ١٠١."}],[146,"وسمعته يقول: راشد ابن داود. أبو المهلب حمصي ضعيف لا يعتبر به."],[147,"وراشد بن سعد حمصي لا باس به. ويعتبر به إذا لم يحدث عنه متروك."],[148,"وسمعته يقول: رزيق بن أبي سلمى، يروي عن أبي المهزم، بصري يعتبر به. في حرف الزاي وسمعت أب الحسن رحمه الله يقول:"],[149,"زياد بن حدير(1) عن ابن مسعود ثقة يحتج له.","",{"fn":"(1) ابن حدير- بمهملة مصغرا تقريب التهذيب ١٠٩."}],[150,"وزياد بن عبد الله النخعي هو نخعي يعتبر به(1) لم يحدث به فيما أعلم غير العباس بن ذريح(2).","",{"fn":"(1) قال الذهبي عن الدارقطني: أنه قال فيه مجهول وأقره الحافظ ابن حجر، لكنه أضاف ما قاله البرقاني، ميزان الاعتدال ٢/٩١، لسان الميزان ٢/٤٩٥.\n(2) ابن ذريح – بفتح المعجمة وكسر الراء وآخره مهملة- تقريب التهذيب ١٦٥."}],[151,"وزياد بن أبي زيد الجصاص، متروك متروك، بصري أقام بواسط."],[152,"وزياد بن الحسن بن فرات القزاز لا بأس به ولا يحتج به، كوفي.. وأبوه وجده ثقتان."],[153,"وزباد بن أبي مريم روى عن عبد الكريم الجزري: حراني ثقة."],[154,"وسمعته يقول: زكريا بن منظور(1) أبو يحي القرظي مدني متروك.","",{"fn":"(1) ويقال زكريا بن يحي بن منظور تقريب التهذيب ١٠٧."}],[155,"وزكريا بن يحي الطاحي متروك، بصري."],[156,"وزكريا بن أبي مريم(1) () ٥ وقع إلى واسط حدث عنه هشيم لا بأس به.","",{"fn":"(1) فيه كلمة غير واضحة، وأقرب إلى الواقع أن تكون كلمة هي: وأمه سلمى."}],[157,"وسمعته يقول: زيادة بن خراش يعتبر به له حديث عن ابن أبزى عن أبيه علي في الجنائز."],[158,"سألته عن حديث رواه الزبرقان بن عبد الله بن عمرو بن أمية عن زهرة عن زيد بن ثابت، فقال يخرج الحديث وزهرة(1) مجهول.","",{"fn":"(1) قال الحافظ ابن حجر: مجهول من الثالثة –س- التقريب ١٠٨. والحديث الذي أشار إليه المصنف وأو رده المزي في تحفة الأشراف ٣/٢١٤."}],[159,"زسمعته يقول: زيد بن سلام بن أبي سلام عن جده ثقتان. قال البرقاني رحمه الله: واسم أبي سلام ممطور."],[160,"وسمعته يقول: أبو أسامة زيد بن علي ثقة."],[161,"وسألته عن زيد بن إسحاق السلولي، فقال كنيته أبو إسحاق بصري يعتبر به."],[162,"وسألته عن زهير بن سالم عن ثوبان، فقال: هو حمصي منكر(1) لم يسمع من ثوبان.","",{"fn":"(1) قال الحافظ: قال الدارقطني في الجرح والتعديل: حمصي منكر الحديث تهذيب التهذيب ٣/٣٤٤."}],[163,"وسألته عن زياد بن صبيح الجهني(1) فقال بصري يعتبر به.","",{"fn":"(1) زياد بن صبيح – بالتصغير- ثقة من الرابعة تقريب التهذيب ١١٠."}],[164,"وعن زفر بن الهذيل صاحب أبي حنيفة، فقال ثقة(1). في حرف السين","",{"fn":"(1) قال الذهبي: أحد الفقهاء والزهاد- صدوق وثقه غير واحد، ميزان الاعتدال ٣/٧١."}],[165,"وسمعته يقول: سعيد بن المرزبان، أبو سعد البقال، متروك."],[166,"وسعيد بن سلام، أصله بصري متروك. كان بمكة يحدث بالبواطيل."],[167,"وسعيد بن محمد الوراق كوفي يروي عنه أبو كريب. متروك."],[168,"وسعيد بن راشد هو السمالك، بصري متروك يروي عنه الأنصاري(1).","",{"fn":"(1) ذكره في كتاب الضعفاء تحت رقم ٢٧٢."}],[169,"وسعيد بن زكريا أبو القاسم، كوفي ثقة."],[170,"وسعيد بن السايب الطايفي، يحدث عنه حرمي بن عمارة ثقة."],[171,"وسعيد بن سمعان عن أبي هريرة مدني ثقة."],[172,"وسعيد بن خالد القارظي(1) يحدث عنه ابن أبي ذئب وابن إسحاق مدني يحتج به.","",{"fn":"(1) قال الحافظ: سعيد بن خالد بن قارظ بالظاء المشالة المدني حليف بني زهرة، صدوق من الثالثة، تقريب التهذيب ١٢١."}],[173,"وسعيد بن عنبسة بصري يعتبر به."],[174,"وسعيد بن يزيد أبو شجاع يروي عنه ابن وهب ثقة من أهل مصر."],[175,"وسعيد بن عبيد الهانئ(1) بصري صالح.","",{"fn":"(1) الهنائي بضم الهاء وتخفيف النون تقريب التهذيب ١٢٤."}],[176,"وسعيد وعبد الله ابنا عبد الرحمن بن أبزى لأبيهما صحبة."],[177,"وقلت له سعيد بن زياد الشيباني عن زياد بن صبيح ابن عمر فقال: سعيد لا يحتج به ولكن يعتبر به من أهل البصرة لا أعرف له إلا حديث التصليب(1).","",{"fn":"(1) ونص الحديث: قال وكيع حدثنا سعيد بن زياد قال: صليت إلى جنب ابن عمر فوضعت يدي على خاصرتي فضرب يدي فلما صلى قال: هذا الصلب في الصلاة وكان رسول الله صلى الله عليه وآله وسلم ينهى عنه، أخرجه النسائي وأبو داود. مختصر سنن أبي داود ٢/٤٦٦. تحفة الأشراف ٥/٣٠٩. تهذيب الكمال ١/٤٤٢."}],[178,"سمعته يقول سعيد بت إسحاق بن كعب بن عجرة مدني ثقة حدث عنه مالك."],[179,"وسعيد بن طريف كذاب"],[180,"وسمعته يقول بقية عن سليمان بن أبي داود حراني ضعيف.... وابنه محمد ضعيف أيضا، يلقب بالبومة."],[181,"وسمعته يقول: سليمان بن داود اليمامي يحدث عنه بشر بن الوليد متروك."],[182,"وسألته مرة أخرى فقال سليمان بن داود صاحب يحي بن أبي كثير متروك."],[183,"وسليمان بن أبي عثمان التجيبي مصري متروك(1).","",{"fn":"(1) قال الحافظ الذهبي: مجهول، ميزان الاعتدال ٢/٢١٤."}],[184,"وسليمان بن كثير أبو داود الواسطي هو أخو محمد بن كثير البصري."],[185,"وسليمان بن عمرو بن عبد(1) ثقة هو أبو الهيثم يروي عن أبي سعيد الخدري.","",{"fn":"(1) قال الحافظ ابن حجر: سليمان بن عمرو بن عبد أو عبيد تقريب التهذيب ١٣٥."}],[186,"وأبو الصباح سليمان بن يسير كوفي ضعيف(1).","",{"fn":"(1) سليمان بن يسير ويقال ابن أسير ويقال ابن قسيم تهذيب التهذيب ٤/٢٣٠."}],[187,"قلت له: سيف٤ عن مجاهد عن ا(1)بن سخبرة، فقال هو سيف بن سليمان مكي ثقة.","",{"fn":"(1) قال الحافظ: سيف بن سليمان أو ابن أبي سليمان تقريب التهذيب ١٤٢."}],[188,"وأبو سخبرة عبد الله بن سخبرة(1) أبو معمر صاحب ابن مسعود.","",{"fn":"(1) ابن سخبرة: بفتح المهملة وسكون المعجمة وفتح الموحدة وسكون المعجمة أبو معمر الكوفي ثقة من الثانية تقريب التهذيب ١٧٥.."}],[189,"وسيف بن عمرو الأسيدي(1) كوفي متروك.","",{"fn":"(1) الأسيدي: بضم الألف وفتح السين المهملة وكسر الياء المشددة المنقوطة باثنتين من تحتها الدال المهملة بعدها، اللباب ١/٦١."}],[190,"بن أبي مغيرة كوفي متروك."],[191,"وسيف بن محمد(1) متروك.","",{"fn":"(1) قال في الضعفاء رقم الترجمة: ٢٧٨ ابن أخت الثوري."}],[192,"وسيف بن هارون البرجمي(1) أخو سنان، ضعيف كوفي، متروك.","",{"fn":"(1) البرجمي: بضم الموحدة والجيم تقريب التهذيب ٤٢."}],[193,"وسألته عن سلام بن المسكين بن سويد بن غفلة فقال كوفي."],[194,"وسألته عن سالم بن غيلان يروي عنه ابن وهب فقال بصري متروك."],[195,"قلت له: سلم عن الشعبي فقال قيل أن هذا مسلم بن عبد الرحمن النخعي فإن كان هذا فهو ثقة."],[196,"وسمعته يقول سويد بن إبراهيم الطحان أبو حاتم بصري ليس يعتبر به(1).","",{"fn":"(1) نقل الحافظ من كتاب البرقاني عن الدارقطني أنه قال لين يعتبر به. ولعل ما في الأصل هو الصواب لأن البرقاني ذكره في الضعفاء ومن شرطه ان لا يذكر إلا من كان متروكا. الضعفاء والمتروكون رقم ٧٦، تهذيب التهذيب ٤/٢٧٠."}],[197,"وسويد بن عبد العزيز الواسطي سكن الشام يعتبر به."],[198,"وسويد بن عمرو الكلبي كوفي ثقة."],[199,"سألته عن سوار بن داود أبي حمزة الصيرفي فقال: بصري لا يتابع على أحاديثه فيعتبر به، ثم قال لي: يحدث عنه وكيع فيخطئ في اسمه يقول داود بن سوار."],[200,"سمعته يقول: السفر بن بشير(1) حمصي ولا يعتبر به.","",{"fn":"(1) السفر بسكون الفاء ابن نسير هكذا ذكره الحافظ بالنون والمهملة تقريب التهذيب ١٢٨."}],[201,"وسمير بن نهار عن أبي هريرة مجهول."],[202,"وسألته عن السايب بن حبيش(1) فقال من أهل الشام صالح الحديث حدث عنه زيادة ولا أعلم حدث عنه غيره.","",{"fn":"(1) ابن حبيش- بمهملة وموحدة ومعجمة مصغرا- تقريب التهذيب ١١٦."}],[203,"وسمعته يقول: سنان بن هارون البرجمي أخو سيف يعتبر به."],[204,"وسلمة بن وردان مدني يترك. وفي حرف الشين"],[205,"سألته عن شعيب بن طلحة روى عن معن فقال: من ولد أبي بكر متروك."],[206,"وسألته: عن شعيب بن رزيق(1) فقال: أبو شيبة، ثقة كان بطرسوس ثم سكن الرملة وعسقلان.","",{"fn":"(1) قال الخزرجي: أوله مهملة الخلاصة ١٦٦."}],[207,"وسمعته يقول شرحبيل بن سعد يعتبر به، ضعيف حدث عنه مالك فقال: عن رجل(1).","",{"fn":"(1) قال ابن البرقي: ترك مالك تسميته لضعفه، انتهى بتصرف تهذيب التهذيب ٥/٣٢٢."}],[208,"وسمعته يقول شمر(1) بن عطية كوفي أسدي ثقة.","",{"fn":"(1) شمر – بكسر أوله وسكون الميم تقريب التهذيب ١٤٧."}],[209,"وسألته عن شداد بن سعيد فقال: بصري يعتبر به."],[210,"وقلت له: الأوزاعي عن أبي عمار فقال: هو شداد بن عبد الله ثقة وقال لي مرة أخرى شداد ابو عمار بصري ثقة."],[211,"وسمعته يقول: شهر بن حوشب يخرج من حديثه(1) ما روى عبد الحميد بن بهرام.","",{"fn":"(1) نقل ابن حجر عن الدارقطني أنه قال: يخرج حديثه، وهذا الكلام فيه بتر والصواب ما أثبته في الأصل تهذيب التهذيب ٥/٣٧٢."}],[212,"سألته عن شبل بن العلاء بن عبد الرحمن بن يعقوب الحرفي فقال ليس بالقوي ويخرج حديثه. في حرف الصاد قلت لأبي الحسن رحمه الله."],[213,"صدقة بن عيسى(1) عن أنس قال متروك، كان بالبصرة ثم صار بالكوفة وقيل: عيسى بن صدقة.","",{"fn":"(1) قال الحافظ: ضعيف من السادسة لم يخرجوا له، وهم عبد الغني في ذكره قلت: وقد أورده المزي في تهذيبه وبين ما وهم فيه المقدسي وجعلها ستة أوهام. تهذيب الكمال: ٢/٦٠٤، تقريب التهذيب ١٥٢."}],[214,"قلت له: معمر عن صدقة عن ابن عمر، قال: هو ابن يسار ثقة مكي."],[215,"قلت: هشيم عن صدقة، فقال: هو ابن موسى يروي عن فرقد السبخي وأبي عمران الجوني متروك(1).","",{"fn":"(1) قال الحافظ: صدوق له أوهام من السابعة. تقريب التهذيب ١٥٢."}],[216,"وسمعته يقول: الصلت بن طريف بصري لا بأس به."],[217,"والصلت بن بهرام من أهل الكوفة لا بأس به."],[218,"وسمعته يقول، الصباح بن محارب رازي يعتبر به."],[219,"والصباح بن يحي المزني(1) يروي عن الأعمش كوفي، ثقة.","",{"fn":"(1) قارن بينه وبين الجرح والتعديل ١/١/٤٤٢، لسان الميزان ٣/٨٠."}],[220,"وسألته عن صالح بن أبي الأخضر، فقال هو بصري لا يعتبر به، لأن حديثه عن ابن شهاب، عرض وكتاب وسماع فقيل له، يميز بينهما فقال لا(1).","",{"fn":"(1) قال يحي بن سعيد: قال لنا صالح، حديثي منه ما قرأت على الزهري ومنه ما سمعت ما وجدت في كتاب فلست أفضل ذا من ذا، وقال الحافظ ابن حجر، ضعيف يعتبر به، تهذيب الكمال ٢/٥٣٤، تقريب التهذيب ١٤٨."}],[221,"وسمعته يقول: صفوان بن عمرو ويعتبر به."],[222,"وسمعته يقول: صفدي بن سنان بصري متروك، اسمه عمر. في حرف الضاد سمعت أبا الحسن يقول:"],[223,"الضحاك بن حمرة(1) شامي سكن واسط يعتبر به.","",{"fn":"(1) الضحاك بن حمرة بالارء المهملة، وقال البرقاني عن الدارقطني: ليس بالقوي يعتبر به. تهذيب التهذيب ٤/٤٤٣."}],[224,"والضحاك بن عبد الله القرشي، مدني ثقة يحتج به يروي عن أنس."],[225,"والضحاك بن مزاحم ثقة لم يسمع من ابن عباس شيئا."],[226,"وسمعته يقول: ضمام(1) بن إسماعيل متروك يحدث عن موسى بن وردان عن أبي هريرة.","",{"fn":"(1) ضمام بكسر أوله مخففا: قال الذهبي: صالح الحديث لينه بعضهم بلا حجة. ميزان الاعتدال ٢/٣٠٩، تقريب التهذيب ١٥٥."}],[227,"قلت: الثوري عن أبي سنان، قال: ضرار بن مرة كوفي ثقة فاضل. في حرف الطا"],[228,"قلت لأبي الحسن: ابن فضيل عن أبي سفيان فقال: اسمه طريف السعدي ويقال: ابن شهاب متروك(1) يحدث عن أبي نضرة وغيره.","",{"fn":"(1) قال في الضعفاء رقم:٣٠٤، طريف بن شهاب ضعيف."}],[229,"قلت له طليق٤ بن محمد عن عم(1)ران بن حصين فقال: مرسل وطليق لا يحتج به، ليس حديثه نيرا.","",{"fn":"(1) طليق بالتصغير، وقال الذهبي: وثق، الكاشف ٢/٤٦، تقريب التهذيب ١٥٨."}],[230,"وسألته عن طعمة بن عمرو الجعفري الكوفي، فقال: ليس بحجة(1) ويعتبر به.","",{"fn":"(1) قال الذهبي: قال الدارقطني: ليس بحجة وقد وثقه ابن معين ميزان الاعتدال ٢/٣٣٧."}],[231,"وسمعته يقول: أبو تميمة الهجيمي٦ اسمه طريف بن مجالد بصري ثقة."],[232,"وقلت له: الطيب بن سلمان عن عمرة، فقال شيخ ضعيف بصري. في باب العين ... من ذلك العباد له. سألت أبا الحسن الدارقطني رحمه الله ونضر وجهه وغفر لنا وله ولجميع المسلمين."],[233,"عن عبد الله بن كرز عن نافع فقال مجهول(1).","",{"fn":"(1) ذكره الحافظ ابن حجر في ترجمة اختلاف العلماء فيه من حيث جرحه ونسبه واسمه لسان الميزان ٣/٣١٢."}],[234,"وعن عبد الله بن جعفر(1) يحدث عن المقري فقال: هو والد علي.","",{"fn":"(1) قال في الضعفاء: كثير المناكير، رقم الترجمة ٣١٠."}],[235,"وعن عبد الله بن عطاء، فقال: كوفي كان بمكة ليس به بأس."],[236,"وعن عبد الله بن زياد عن عمار وابن مسعود(1) فقال: هو أبو مريم الأسدي كوفي ثقة.","",{"fn":"(1) في الأصل عبد الله بن زياد بن عمار بن مسعود، والتصويب من تهذيب التهذيب ٥/٣٢١."}],[237,"وعن عبد الله بن الزبير الباهلي يروى عن ثابت فقال: شيخ بصري صالح."],[238,"وعن عبد الله بن نافع مولى ابن عمر فقال: متروك."],[239,"وعن عبد الله بن الأسود القرشي شيخ ابن وهب فقال: مصري لا بأس به(1).","",{"fn":"(1) قال أبو حاتم: شيخ لا أعلم روى عنه غير أبي وهب، الجرح ٢/٢/٢."}],[240,"وعن عبد الله بن شريك العامري فقال: كوفي لا باس به، قلت يروي عن ابن عمر وأبي الزبير(1) فقال: سماع منهما.","",{"fn":"(1) قال الحافظ: قال البرقاني عن الدارقطني: لا بأس به سمع من ابن عمر وابن الزبير تهذيب التهذيب ٥/٣٥٣."}],[241,"سألته عن عبد الله بن هارون بن عنترة(1) فقال متروك يكذب وأبوه يحتج به وحده.","",{"fn":"(1) ابن عنترة بنون ثم مثناة، والابن اسمه عبد الملك وليس عبد الله كما في الأصل تقريب التهذيب ٣٦١. لسان الميزان ٤/٧٢، تهذيب التهذيب ١/١٠."}],[242,"أبو وكيع٢ يعتبر به روى(1) عن علي رضي الله عنه.","",{"fn":"(1) هو عنترة بن عبد الرحمن الكوفي الشيباني تهذيب التهذيب ٨/١٦٢."}],[243,"وسألته عن عبد الله بن يزيد مولى المنبعث فقال: يعتبر به."],[244,"قلت ابن أبي فديك يروي عن عبد الله بن يزيد عن أبيه عن أبي هريرة فقال: إن كان هذا يزيد مولى المنبعث فهو ثقة."],[245,"سألته عن عبد الله بن نافع الصايغ، فقال: مدني فقيه يعتبر به."],[246,"وعن عبد الله بن الأجلح، فقال كوفي لا بأس به."],[247,"وعن عبد الله بن عبد الرحمن بن يعلى روى عنه وكيع فقال: طايفي يعتبر به."],[248,"وعن عبد الله بن عبد الرحمن بن معمر بن حزم فقال: أبو طواله(1)، مدني ثقة.","",{"fn":"(1) أبو طوالة بضم المهملة قال الدقاق: لا يعرف في المحديثين من يكنى أبا طوالة سواه. تقريب التهذيب ١٨٠. تهذيب التهذيب ٥/٢٩٧."}],[249,"وسمعته يقول: أبو عامر الهوزاني هو عبد الله بن نجي(1) حمصي لا بأس به.","",{"fn":"(1) نجى: بنون وجيم مصغرة تقريب التهذيب ١٩٢."}],[250,"سألته عن عبد الله بن محمد العدوي، يحدث عن علي بن زيد بن جدعان فقال: متروك."],[251,"قلت لأبي الحسن أبو صادق عن أبي هريرة فقال: اسمه عبد الله."],[252,"بن ناجد أخوربيعة بن ناجد كذا يقول أبو نعيم، ويقال أبو صادق اسمه مسلم بن يزيد ويقال هما رجلان أحدهما مسلم والآخر عبد الله بن ناجد."],[253,"وسمعته يقول عبد الله بن عقيل أبو عقيل، أثنى عليه أحمد، يروي عنه أبو النضر الكوفي."],[254,"وعبد الله بن عروة بن الزبير أحد الأثبات الثقات."],[255,"وعبد الله بن غابر(1) أبو عامر الألهاني حمصي لا بأس به.","",{"fn":"(1) عبد الله بن غابر –بمعجمة ثم موحدة- تقريب التهذيب ١٨٤."}],[256,"وعبد الله بن أبي الهذيل عن ابن مسعود كوفي."],[257,"وعبد الله بن حسين قاضي سجستان وقع إلى البصرة يعتبر به."],[258,"فقلت له روى عبد الله بن الحسن الهاشمي عن أمه عن جدته، فقال أمه فاطمة بنت الحسين وجدته هي فاطة الكبرى بنت النبي رضي الله عنها، لم تسمع أمه عنها(1) ويخرج حديثه.","",{"fn":"(1) تهذيب التهذيب: ١٢/٤٤١."}],[259,"فقلت له عبد الله بن الوليد عن أبيه عن أبي هريرة، فقال: ابن الوليد هو مصري لا يعتبر به ليس هو بالذي حدث عنه أحمد بن حنبل، وابن حجيرة هو عبد الرحمن بن حجيرة(1) مصري معروف، ولا يثبت هذا الحديث.","",{"fn":"(1) في تهذيب الكمال عبد الله بن عبد الرحمن بن حجيرة"}],[260,"وسمعته يقول: إسماعيل بن عياش عن عبد الله بن دينار هو البهراني حمصي ضعيف لا يعتبر به. باب في عبد الرحمن"],[261,"وسألته عن أبي بكر عبد الرحمن بن وردان الغفاري يروي عن أنس فقال: مدني يعتبر به(1) وليس بأخي سلمة بن وردان.","",{"fn":"(1) نقل الذهبي في ميزانه عن الدارقطني انه قال فيه ليس بقوي. وحكم عليه في الكاشف بأنه صدوق، ونقل الحافظ ابن حجر عن الدارقطني أنه قال فيه ليس بالقوي وفي تقريب التهذيب أنه مقبول. وبالرجوع إلى كتاب الضعفاء لم أجد له ذكرا. ميزان الاعتدال ٢/٥٩٢، الكاشف ٢/١٩٠، تهذيب التهذيب ٦/٢٩٣، تقريب التهذيب ٢١١."}],[262,"سألته عن عبد الرحمن بن(1) أبي حدود عن أبي هريرة فقال: لا بأس به.","",{"fn":"(1) ليست في النسخة والأمر يقتضيه، وقد ذكر الحافظ ابن حجر عن الدارقطني أنه قال في الراوي عن محمد بن كليب بن جابر. متروك وقال في الراوي عن سليمان بن قته عقب روايته عنه عن أبي سعيد في كتاب السنن كلهم ثقات، تهذيب التهذيب ٦/٢٨٧."}],[263,"قلت له: عبد الرحمن بن بشر بن مسعود الأنصاري عن النبي صلى الله عليه وسلم فقال: مرسل، إنما يحدث عن أبي سعيد الخدري ويحدث عنه ابن سيرين."],[264,"سألته عن عبد الرحمن بن عبد الله بن دينار فقال: أخرج عنه البخاري وهو عند غيره، ضعيف فيعتبر به(1).","",{"fn":"(1) قال السلمي عن الدارقطني، خالف فيه البخاري الناس وليس بمتروك وقال الحاكم عن الدارقطني إنما حدث بأحاديث يسيرة. تهذيب التهذيب ٦/٢٠٧."}],[265,"وسمعته يقول: عبد الرحمن بن حسان الكناني حمصي لا بأس به."],[266,"وعبد الرحمن بن الحارث بن هشام يروي عن علي سمع منه خليل المدني."],[267,"قلت له: عبد الرحمن بن علقمة عن النبي صلى الله عليه وسلم فقال: لا تصح صحبته ولا يعرف(1).","",{"fn":"(1) وفي التهذيب:- قال الدارقطني لا تصح له صحبة ولا نعرفه، تهذيب التهذيب ٢/٢٣٣."}],[268,"وسمعته يقول: عبد الرحمن بن مطعم هو أبو المنهال، ثقة."],[269,"وعبد الرحمن بن معاوية هو من ولد عتبة بن أبي سفيان."],[270,"قلت له: عبد الرحمن بن مهران عن أبي هريرة فقال: شيخ مدني يعتبر به."],[271,"قلت له: روى حفص بن غياث عن عبد الرحمن جليس مسعر، قال: مجهول."],[272,"قلت له: عبد الرحمن بن أبي ذباب عن أبيه عن عثمان فقال لا يعرف له غير هذا."],[273,"سألته عن عبد الرحمن بن١ النعمان الأنصاري فقال: متروك."],[274,"وعن عبد الرحمن بن نافع بن جبير الزهري فقال: مجهوا، وأبوه معروف."],[275,"وسمعته يقول عبد الرحمن بن عبد الملك بن أبجر(1) من أهل الكوغة ثقة.","",{"fn":"(1) ابن أبحر. بموحدة وجيم وراء وزن أحمد. تقريب التهذيب ٢٠٦."}],[276,"سألته عن عبد الرحمن بن عبد الله بن سابط فقال: هو ابن أبي حميضة ثقة مكي يروي عن أبي أمامة."],[277,"وسألته عن عبد الرحمن بن محمد يروي عن السايب بن يزيد فقال: هو شيخ مدني لا أدري من هو، يعتبر به(1).","",{"fn":"(1) انظر لسان الميزان ٣/٤٢٩."}],[278,"سألته عن عبد الرحمن بن إبراهيم يروي عن العلاء بن عبد الرحمن فقال هو بصري لا بأس به(1).","",{"fn":"(1) نقل الحافط الذهبي عن الدارقطني أنه ضعفه. ولا أدري أين؟ ومن أقوال الأئمة فيه تبين انه لا ينزل عن الرتبة التي ذكرها البرقاني عن الدارقطني."}],[279,"قلت له ابن أبي ذئب عن عبد الرحمن بن مهران عن عبد الرحمن(1) بن سعد، فقال هذا عبد الرحمن أيضا مدني يعتبر به. وعبد الرحمن بن سعد، صالح مدني كناه الزهري أبا حميد وسماه صفوان بن سليم.","",{"fn":"(1) ليست في النسخة."}],[280,"عبد الرحمن – ثم سقط على كلمة قالها الدارقطني من الرقعة أظنها الأعرج(1).","",{"fn":"(1) هو عبد الرحمن ابن هرمز الأعرج قال فيه الحافظ ثقة ثبتعالم من الثالثة. تقريب التهذيب ٢١١."}],[281,"قلت له: عبد الرحمن الأصم روى عنه عبد الحكم قائد سعيد بن أبي عروبة قال: بصري ثقة(1).","",{"fn":"(1) قال الحافظ عبد الرحمن الأصم واسمه عبد الله ويقال عمر وأبو بكر العبدي المدائني مؤذن الحجاج. صدوق من الثالثة –م س- تقريب التهذيب ١٩٩."}],[282,"وسمعته يقول عبد الرحمن بن أبي الرجال(1) ثقة مدني. عبد العزيز","",{"fn":"(1) ابن أبي الرجال بكسر الراء ثم جيم واسمه محمد. تقريب التهذيب ٢٠١."}],[283,"سألته عن عبد العزيز بن المطلب فقال: شيخ مدني يعتبر به."],[284,"وأبوه المطلب بن عبد المطلب بن حنطب ثقة."],[285,"وأخوه الحكم بن المطلب يقاربه يعتبر به."],[286,"قلت له: عبد العزيز بن جريج عن عائشة قال: مجهول، وقيل هو والد ابن جريج فإن كان هو فلم يسمع من عائشة(1)، يترك هذا الحديث.","",{"fn":"(1) في تهذيب التهذيب قال البرقاني عن الدارقطني مجهول قيل له هو والد عبد الملك قال إن كان فلم يسمع من عائشة ٢/٣٣٣."}],[287,"قلت له: عبد العزيز الدباغ عن الداناج عن عكرمة فقال: عبد العزيز هو ابن مختار القفة، والد اناج اسمه عبد الله بن فيروز ثقة، عن عكرمة سماع ر٢٩٩- وسمعته يقول: عبد العزيز بن عبد الله بن حمزة صاحب النبي صلى الله عليه وسلم حمصي متروك. عبد الملك قلت لأبي الحسن:"],[288,"عبد الملك عن أبي سلمة من هو؟ فقال: عبد الملك بن أبي سليمان ثقة."],[289,"وسمعته يقول: عبد الملك بن قدامة الجمحي مدني يترك."],[290,"وعبد الملك بن محمد بن نصير١ أبو حذيفة عنه، مجهولان."],[291,"وعبد الملك بن أبي زهير الثقفي يحدث عنه سعيد بن السايب الطائفي شيخ مقل ليس بالمشهور يخرج حديثه."],[292,"وعبد الملك بن عبد الملك روى عنه عمر بن الحارث مدني متروك. عبد الكريم"],[293,"قلت له عبد الكريم عن زياد بن أبي مريم، فقال: هو الجزري ثقة."],[294,"قلت فابن أبي ليلى عن عبد الكريم، فقال: هذا أبو أمية البصري يترك. عبد الواحد"],[295,"وسمعته يقول: عبد الواحد بن عبد الله النضري(1) ثقة من أهل حمص ولأي أمارة المدينة محمود الأمارة.","",{"fn":"(1) قال السخاوي، النضرى بمعجمة. قلت:- وفي الأصل. البصرى:- التحفة اللطيفة ٣/١٠٠."}],[296,"وعبد الواحد بن ميمون مولى عروة، كنيته أبو حمزة متروك صاحب مناكير(1).","",{"fn":"(1) لسان الميزان ٤/٨٣."}],[297,"وعبد الواحد بن أبي عون ثقة مدني يحدث عن سعد بن إبراهيم. عبد الحكيم"],[298,"سألته عن أبي سفيان الواسطي حدث عنه إسحاق بن شاهين فقال اسمه عبد الحكيم بن منصور متروك."],[299,"وسألته عن عبد الحكيم(1) بن عبد الله بن أبي فروة فقال لي شيخ مقل مدني يعتبر به إذا حدث عن غير الواقدي.","",{"fn":"(1) ذكر في لسان الميزان ٣/٣٩٤. والتحفة اللطيفة ٢/٤٥٢ باسم عبد الحكم. وفي ميزان الاعتدال ٢/٥٣٧ مثل ما ذكره في أصل المخطوط."}],[300,"قلت له فعبد الحكيم قائد سعيد بن أبي عروبة، فقال: بصري يترك. جماعة متفرقون سمعت أب الحسن الدارقطني رحمه الله يقول:"],[301,"عبد المنعم بن نعيم أبو سعيد الرياحي من أهل خوزستان متروك(1).","",{"fn":"(1) ذكر في الضعفاء عن الدارقطني أنه قال عبد المنعم ابن نعيم أبو سعيد بصري رياحي عن يحيى بن مسلم مجهول لا يعرف إلا به وعن الأعمش، الضعفاء رقم الترجمة ٣٠٦."}],[302,"وعبد المنعم بن بشير مصري متروك(1).","",{"fn":"(1) قال فيه مرة ضعيف، لسان الميزان ٤/٧٥."}],[303,"وعبد الرحيم بن هارون الغساني متروك يكذب، واسطي إن شاء الله وكان ببغداد(1).","",{"fn":"(1) تاريخ بغداد ١١/٨٥."}],[304,"وعبد الغفار بن القاسم أبو مريم متروك، ثم قال: شيخ شعبة أثنى عليه شعبة وخفي على شعبة وبقي بعد شعبة فخلط(1).","",{"fn":"(1) في لسان الميزان ٤/٤٢، قال الدارقطني متروك وهو شيخ شعبة أثنى عليه شعبة وخفي على شعبة أمره فبقي بعد شعبة فخلط."}],[305,"وعبد المجيد بن عبد العزيز بن أب رواد(1) لا يحتج به، ويعتبر به، وأبوه أيضا لين والإبن أثبت، قيل أنه مرجئ ولا يعتبر بأبيه يترك وهما مكيان.","",{"fn":"(1) ابن أبي رواد. بفتح الراء وتشديد الواو. تقريب التهذيب ٢١٨."}],[306,"وعبد الكريم بن عبد المجيد، هو أبو بكر الحنفي وهم أربعة إخوة هذا."],[307,"وأخوه عبيد الله بن عبد المجيد أبو علي وشريك وعمير، لا يعتمد منهم إلا على أبي بكر وأبي علي."],[308,"وعبد الوهاب بن الضحاك العرضي(1) متروك.","",{"fn":"(1) العرضى. بضم المهملة وسكون الراء بعدها معجمة. تقريب التهذيب ٢٢٢."}],[309,"وعبد الأعلى بن عامر الثعلبي(1) روى عن ابن أبي ليلى، يعتبر به.","",{"fn":"(1) الثعلبي قال الحافظ بالمثلثة والمهملة. قال الدارقطني يعتبر به وقال في العلل ليس بالقوي عندهم. تقريب التهذيب ١٩٥، تهذيب التهذيب ٦/٩٥."}],[310,"وعبد الحميد بن محمود كوفي يحتج به."],[311,"وعبد الحميد بن أمية عن أنس لا شيء."],[312,"وعبد القدوس بن الحجاج أبو المغيرة يروي عن الأوزاعي ثقة."],[313,"وعبد الجبار بن عمر الأيلي أبو عمر متروك."],[314,"عبيد بن خنيس(1) العبدي، قال الدارقطني متروك.","",{"fn":"(1) قال الحافظ هذا هو عبيد الله بن حنش. لسان الميزان ٤/١١٩."}],[315,"وعبيد بن الحشحاش(1) عن أبي ذر متروك.","",{"fn":"(1) قال الحافظ، ابن الخشخاش بمعجمات وقيل بمهملات. تقريب التهذيب ٢٢٩."}],[316,"وعبيد بن حسان قال لي: جزري متروك."],[317,"وعبيد بن الأسود يعتبر به."],[318,"وسمعته يقول: عباد بن أحمد العرزمي يحدث عنه المقانعي (1) متروك.","",{"fn":"(1) المقانعي على بن العباس. ميزان الاعتدال ٢/٣٦٥."}],[319,"وعباد بن سعيد بصري، متروك يحدث عن مبشر ابن أبي المليح."],[320,"قلت له: أبو ظفر عبد السلام بن مطهر بن الحسام بن مصك بن شيطان شيخ أبي خليفة، كذا نسبه، قال نعم، بصري ثقة."],[321,"وسألته عن عبد الرزاق بن عمر الدمشقي، فقال: ضعيف، فقيل من أي شيء ضعفه، فقال قيل أن كتابه عن الزهري ضاع، فقيل هو في معنى صالح بن أبي الأخضر؟ فقال. ذاك فوق عبد الرزاق(1).٢ وسألت عنه مرة أخرى فقال: هو ضعيف يعتبر به ويكنى أبا بكر. آخر الجزء الأول ويتلوه في الجزء الثاني الذي يليه باب بقية العين. بسم الله الرحمن الرحيم قال أبو بكر أحمد بن محمد بن أحمد بن غالب البرقاني الحافظ: سألت الحافظ أبا الحسن بن عمر الدارقطني رحمه الله قلت له:","",{"fn":"(1) في تهذيب التهذيب ٦/٣١٠، قيل له هو في معنى صالح بن الأخضر قال ذاك دونه، وقارن بينه وبين ترجمة صالح بن الاخضر تهذيب التهذيب ٤/٣٨٠"}],[322,"عنبسة١ بن سعيد بن ال(1)عاص عن أبي هريرة فقال: هذا جليس الحجاج وهو عم إسماعيل بن أمية.","",{"fn":"(1) عنبسة:- بفتح أوله ثم نون ساكنة ثم موحدة ومهملة مفتوحتين. تقريب التهذيب ٦٦."}],[323,"قلت: فعنبسة بن سعيد بن كثير قال: هو ابن أبي العنبس كوفي يعتبر به."],[324,"قلت: فعنبسة بن سعيد القطان قال: هذا أخو أبي الربيع السمان بصري متروك(1).","",{"fn":"(1) وفي الضعفاء رقم ٤١٦ ضعيف عن الزهري."}],[325,"قلت: فعنبسة بن سعيد الأموي فقال: هذا اخو يحي ومحمد وعبد الله وعبيد وأبان، كلهم ثقات(1).","",{"fn":"(1) تاريخ بغداد ١٢/٢٨٤."}],[326,"وسمعته يقول: عاصم الأحول عداده في البصريين، وعاصم بن أبي النجود(1)، والأحول أثبت ثم قال لي: ابن أبي النجود في حفظه شيء.","",{"fn":"(1) ابن أبي النجود بنون وجيم. تقريب التهذيب"}],[327,"وعاصم بن عبيد الله المدني يترك، هو مغفل."],[328,"وعاصم بن هلال، أبو النضر بصري لا بأس به."],[329,"قلت له: فعاصم بن حميد السكوني يروي عن معاذ، قال هو من أصحابه ثقة."],[330,"سألته عن عامر بن صالح بن عبد الله بن عروة بن الزبير بن العوام شيخ أحمد بن حنبل ويحي بن معين، فقال أساء القول فيه ابن معين(1)، ولم يتبين أمره عند أحمد(2) وهو مدني يترك عندي.","",{"fn":"(1) نقل عن ابن معين أنه قال صالح كذاب خبيث عدو الله. ونقل عنه مرة أنه قال فيه لم يكن حديثه بشيء كان ضعيف الحديث. التاريخ ٢/٢٨٨، تهذيب التهذيب ٥/٧١.\n(2) قال فيه الإمام أحمد. ثقة لم يكن صاحب حديث. اعلل ومعرفة الرجال ١٣٤."}],[331,"قلت: فعامر بن جشيب(1) يروي عن أبي الدرداء قال: حمصي ثقة لم يسمع من أبي الدرداء.","",{"fn":"(1) جشيب بفتح الجيم وكسر المعجمة وآخره موحدة. تقريب التهذيب ١٦٠."}],[332,"وسألته عن عامر بن عبيدة الباهلي فقال: بصري لا بأس به."],[333,"سالت أبا الحسن عن عمر بن راشد المدني يروي عن هشام بن عروة ومالك بن عبد الرحمن بن حرملة، فقال: يقال له الجاري كان يكون بالجار متروك(1).","",{"fn":"(1) نقل الحافظ عن الداقطني أنه قال. كان ضعيفا لم يكن مرضيا وكان يهتم بوضع الحديث. لسان الميزان ٤/٣٠٤."}],[334,"وسمعته يقول: عمر بن عبد الرحمن بن قيس بن الأبار(1) أبو حفص كوفي ثقة.","",{"fn":"(1) الأبار- بتشديد الموحدة. تقريب التهذيب ٢٥٥."}],[335,"وسألته عن عمر بن موسى الأنصاري، فقال كوفي متروك."],[336,"وعن عمر بن خالد القى، فقال: لا بأس يه."],[337,"وسئل عن عمر بن إبراهيم يروي عن قتادة فقال: بصري لين يترك."],[338,"وعن عمر بن يزيد فقال: كوفي أزدي كنيته أبو سعيد، متروك روى أبو كريب عنه."],[339,"قلت له: فعمر بن وهب الخزاعي، قال بصري معروف لا بأس به لا يعرف اسم أبيه(1).","",{"fn":"(1) الجرح والتعديل ١/٣/١٤٠."}],[340,"قلت: روى المقانعي(1) عن عمر بن محمد بن الحسن عن أبيه، قال لا بأس بهما.","",{"fn":"(1) المقانعي بفتح الميم والقاف وسكون الألف وكسر النون والعين المهملة، اللباب ٣/٢٤٥."}],[341,"قلت: عمر بن بشير بن المحرر عن أبيه، ويقال عمران بن بشير، قال: حدث عن أبيه، سعيد المقبري، يعتبر به وأبيه بشير."],[342,"وسمعته يقول: عمر بن زرارة الحدثي(1) ثقة، من مدينة في الثغر يقال لها الحدث.","",{"fn":"(1) الحدثي. بفتح الحاء والدال المهملتين وبعدهما الثاء المثلثة. اللباب ١/٣٤٨."}],[343,"فأما عمرو بن زرارة فهو نيسابوري ثقة أيضا."],[344,"سالته عن عثمان بن عمير أبي اليقظان، فقال كوفي يعتبر به."],[345,"قلت: وكيع عن عثمان الحشام(1) فقال هو بصري يعتبر به.","",{"fn":"(1) يقال اسم أبيه ميمون. أو عبد الله. تقريب التهذيب ٢٣٦."}],[346,"قلت فعثمان بن واقد، قال عمري كوفي لا بأس به يحدث عن نافع."],[347,"وسمعته يقول: عثمان بن مسلم البتي(1) ثقة.","",{"fn":"(1) البتي:- بفتح المهملة وتشديد المثناة. تقريب التهذيب ٢٣٦."}],[348,"قلت له: روى هشيم عن عثمان بن حكيم عن سهل بن حنيف، فقال: أخطأ في نسبه إنما هو عثمان بن حكيم بن عباد بن حنيف أخو سهل بن حنيف."],[349,"سألته عن علي بن زيد بن جدعان. فقال: هو علي بن زيد بن جدعان بن عبد الله بن أبي مليكة بن عبد الله بن جدعان، ثم قال لي: أنا أقف فيه لا يترك عندي. فيه لين(1).١.","",{"fn":"(1) في تهذيب التهذيب ٧/٣٢٣، قال الدارقطني أنا أقف فيه لا يزال عندي فيه لين."}],[350,"وسئل عن علي بن هاشم بن البريد فقال: قال أحمد هو أول من كتبنا عنه(1).","",{"fn":"(1) وفي كتاب العلل ص١٩٩، قال أبي سمعت من علي بن هاشم بن البريد مجلسا واحدا."}],[351,"وسألته عن علي بن غراب(1) فقال كوفي يعتبر به.","",{"fn":"(1) قال الحافظ علي بن الغراب باسم الطائر. تقريب التهذيب ٢٤٨."}],[352,"وعن علي بن عابس(1) فقال: كوفي يعتبر به.","",{"fn":"(1) ابن عباس، بموحدة مكسورة بعدها مهملة. تقريب التهذيب ٢٤٧."}],[353,"وعن علي بن خلف الدؤلي، فقال: شيخ مدني يعتبر به."],[354,"وعن علي بن الحسين بن أبي بردة،.فقال: كوفي صالح."],[355,"وعن علي بن أبي فاطمة(1) يحدث عنه يونس بن بكير، فقال مجهول يترك.","",{"fn":"(1) هو علي بن الحزور بفتح المهملة والزاي والواو المشددة بعدها راء قال الحافظ. قال الدارقطني في علي بن الحزور ضعيف وقال في ابن أبي فاطمة مجهول يترك كان فرق بينهما قلت. وضبي الدارقطني في ضعفائه يدل على أنهما واحد حيث قال في الترجمة رقم ٤٠٦ علي بن حزور وهو ابن أبي فاطمة ونقل الذهبي في ميزانه عن الدارقطني أنه قال:- علي بن الحزور ضعيف ويقال له علي بن أبي فاطمة يدلس بذلك. ميزان الاعتدال ٣/١١٨، تهذيب التهذيب ٧/٢٩٧، تقريب التهذيب ٢٤٤."}],[356,"وعن علي بن الحسن الشامي، فقال مصري يكذب يروي عن الثقات بواطل مالك والثوري وابن أبي ذئب."],[357,"سمعته يقول عمرو بن مالك الجنبي (1) أبو علي، مصري لا بأس به، ثم قال ثقة.","",{"fn":"(1) الجنبي، بفتح الجيم وسكون النون بعدها موحدة. تقريب التهذيب ٢٦٢."}],[358,"وعمرو بن أبي الحجاج ثقة مصري، هو والد أبي معمر المنقري صاحب عبد الوارث."],[359,"وعمرو بن شمر كوفيي متروك."],[360,"وعمرو بن أبي نعيمة المعافري مجهول مصري يترك(1).","",{"fn":"(1) في تهذيب التهذيب ٨/١١١، قال الدارقطني. مصري مجهول يترك."}],[361,"وعمرو بن خالد أبو حفص الأعشى متروك. وقال مرة أخرى عمرو بن خالد الواسطي متروك(1) يحدث عن زيد بن علي وأبي هاشم الرماني وحبيب بن أبي ثابت.","",{"fn":"(1) وقال في الضعفاء رقم ٣٩٩.كذاب."}],[362,"وسألته عن حديث عمارة بن غزية عن أنس عن عمر عن النبي صلى الله عليه وسلم في فضل عمارة(1) فقال مرسل لم يلحق عمارة أنسا، وهوثقة.","",{"fn":"(1) لعل كلمة في فضل عمارة. خطأ والصواب أنه روي حديثا في فضل الجماعة وهو عند الدارقطني بلفظ: من صلى في مسجد جماعة أربعين ليلة. انظر سنن الدارقطني ٣/٣٨، جامع التحصيل ٢٩٦."}],[363,"وسمعته يقول عمارة بن زاذان الصيدلاني بصري ضعيف لا يعتبر به."],[364,"وأبو معشر عمارة بن صدقة كوفي يحدث عنه أبو كريب، ثقة."],[365,"وعمار بن سيف الضبي كوفي متروك."],[366,"وعمار بن يزيد مجهول يحدث عن موسى بن هلال الطويل."],[367,"وعمران بن الجعد وقيل ابن أبي الجعد كوفي(1) ثقة يحدث عن عمر، مرسل.","",{"fn":"(1) فرق ابن أبي حاتم بين عمران بن الجعد وابن أبي الجعد وسكت عنهما الجرح والتعديل ١/٣/٢٩٥."}],[368,"وعمير بن مأمون عن الحسن بن علي، لا شيء. سمعت أبا الحسن يقول:"],[369,"عون بن سلام٢ لا بأس به(1).","",{"fn":"(1) سلام. بتشديد اللام. تقريب التهذيب ٢٦٨."}],[370,"وعون بن ذكوان القصاب، بصري أبو جناب متروك."],[371,"وعون مولى أم حكيم عن الزهري مديني ثقة(1).٣.","",{"fn":"(1) الجرح والتعديل ١/٣/٣٨٦."}],[372,"وعون بن معمر شيخ خرساني سكن البصرة ليس به بأس(1).","",{"fn":"(1) نقل ابن أبي الحاتم أقوال الأئمة فيه. وتوثيق الدارقطني موافق لأبي زرعة الجرح ١/٣/٣٨٧."}],[373,"وعون بن عبد الله(1) عن عبد الله بن مسعود مرسل.","",{"fn":"(1) هو ابن عتبة بن مسعود. جامع التحصيل ٣٠٥."}],[374,"عيسى بن المختار بن عبد الله بن أبي ليلى ثقة."],[375,"وعيسى بن ميسرة أبو عيسى الخياط متروك(1) وأخوه موسى يعتبر به.","",{"fn":"(1) وفي الضعفاء الترجمة رقم ٤٠٩ عيسى ابن أبي عيسى الحناط مدني عن الشعبي وأخزه موسى بن أبي عيسى صالح الحديث. واسم أبي عيسى ميسرة."}],[376,"وعيسى بن عمر يحدث عنه عمرو بن يحي بن عمارة، هو مديني معروف يعتبر به."],[377,"وعيسى بن مسلم هو أبو داود الطهوي من بني طهية كوفي متروك."],[378,"قلت له محمد بن زيد بن مهاجر عن ابن سيلان من هو(1)؟ ١ فقال: قد قيل اسمه عيسى وقيل عبد ربه مديني يعتبر به.","",{"fn":"(1) انظر ما ذكر حوله في تهذيب التهذيب ٢/٤٠."}],[379,"قلت له عيسى بن صدقة(1) قال لا شيء.","",{"fn":"(1) انظر ما ذكر حوله من اختلاف اسنه في لسان الميزان ٤/٣٩٨."}],[380,"سمعته يقول: أبو النجاشي عن رافع اسمه عطاء بن صهيب وقيل غير هذا."],[381,"عباس بن ذريح كوفي ثقة."],[382,"وعوسجة بن الرماح(1) شبه مجهول لا يروي عنه غير عاصم لا يحتج به لكن يعتبر به.","",{"fn":"(1) عوسجة بفتح أوله وسكون الواو وفتح المهملة والميم ابن الرماح بتشديد الميم. تقريب التهذيب ٢٦٨."}],[383,"عتيق بن يعقوب الزبيري مديني ثقة وهو ابن صديق بن موسى(1) بن عبد الله بن الزبير، حدث عن ابن جريج عن صديق.","",{"fn":"(1) في الاصل. وهو ابن صديق موسى. والتصويب من لسان الميزان ٤/١٢٩."}],[384,"عتبة أبو عمر كوفي شيخ لا بأس به، يحدث عن ابن نهشل مجهول يترك حديثه."],[385,"قلت له: فعتبة بن عمرو بن أبي هريرة قال: هو ابن عمرو بن عباس قرشي ثقة، وقال بعضهم: عتبة بن عمرو عن ابن عباس وهذا خطأ."],[386,"سالته عن عفيف بن سالم الموصلي فقال: ربما أخطأ لا يترك."],[387,"قلت له: عدي بن ثابت عن أبيه عن جده عن النبي صلى الله عليه وسلم قال لا يثبت ولا يعرف أبوه ولا جده، وعدي ثقة."],[388,"وقال لي: عدي بن الفضل بصري متروك."],[389,"قلت فعدي بن أرطأة عن عمرو بن عنبسة فقال بصري، يحتج به(1).","",{"fn":"(1) في تهذيب التهذيب ٧/١٦٤. قال البرقاني:- قلت للدارقطني فعدي بن أرطأة بن عمرو بن عيسى. قال يحتج به."}],[390,"قلت عجلان عن أبي هريرة قال هو مولى المشمعل يعتبر به."],[391,"وسمته يقول عكرمة بن عمار يمامي ثقة."],[392,"وعكرمة بن إبراهيم الأزدي كان من أهل الكوفة أقام بالبصرة(1).","",{"fn":"(1) قال يحيى وأبو داود ليس بشيء. وقال النسائي ضعيف. ميزان الاعتدال ٣/٨٩."}],[393,"عياض بن دينار عن أبي هريرة لا أعلم حدث به، غير ابن إسحاق يعتبر به."],[394,"عصام بن قدامة البجلي(1) كوفي يعتبر به.","",{"fn":"(1) قال الحافظ عصام بن قدامة البجلي، أو الجدلي بالجيم تقريب التهذيب ٢٣٩. ٤في الأصل. عبدوس بن كثير والتصويب من تاريخ بغداد ١١/١١٦."}],[395,"وعلوان أبو رهم مجهول يترك، لا يحدث عنه غير ليث بن أبي سليم."],[396,"ابن عتبة أبي الصهباء أبو خريم بصري ثقة."],[397,"عبدوس بن كثير٤ حدثونا عنه لا بأس به من أهل الري، حدث ببغداد قبل الستين يعتبر به."],[398,"وسمعته يقول: عياش بن عقبة الحضرمي ليس به بأس، يقول المقرئ هو ابن لهيعة(1) وليس كذلك، ابن لهيعة هو عبد الله بن لهيعة بن عقبة بن أبي عبد الرحمن وهذا ابن عقبة بن فلان بن تغلب.","",{"fn":"(1) في تهذيب التهذيب ٨/١٩٨، قال المقري. هو عم ابن لهيعة قال الدارقطني والمصريون ينكرون ذلك."}],[399,"وسألته عن عراك بن خالد فقال: لا بأس به."],[400,"قلت له عصمة بن بشير بن الفرع عن المنتفع صاحب النبي صلى الله عليه وسلم، فقال عصمة مجهول، والفرع كذلك، والمنتفع أعرابي من أصحاب النبي صلى الله عليه وسلم(1).","",{"fn":"(1) في ميزان الاعتدال ٣/٢٧. عصمة بن بشير. عن الفرع. قال الدارقطني هما مجهولان. والخبر منكر."}],[401,"سمعته يقول: عروة بن رويم(1) شامي لا بأس به. في حرف الغين","",{"fn":"(1) رويم بالراء مصغرا، تقريب التهذيب ٢٣٨."}],[402,"سمعته يقول: غيلان بن عبد الله عن ابن عمر هو مولى بني مخزوم. ثقة."],[403,"وقلت له: غضيف(1) بن الحارث قال: ثقة من أهل الشام. في حرف الفاء","",{"fn":"(1) غضيف بالضاد المعجمة مصغرا، تقريب التهذيب ٢٧٣."}],[404,"سألته عن الفرج بن فضالة، فقال ضعيف."],[405,"وسمعته يقول: فضيل بن ميسرة أبو معاذ بصري(1). في حرف القاف","",{"fn":"(1) قال أبو حاتم، شيخ صالح الحديث. الجرح والتعديل٢/٢/٧٥."}],[406,"سألته عن قابوس بن أبي ظبيان، فقال: ضعيف ولكن يترك."],[407,"قلت له: قريش بن إبراهيم عن عبد الرحمن بن عبد الملك بن أبجر. فقال: قريشي بغدادي لا بأس به(1).١. في حرف الكاف","",{"fn":"(1) تاريخ بغداد ١٢/٤٧١."}],[408,"سمعته يقول: كريز بن حكيم كان بحلب، منكر الحديث. في اللام"],[409,"سألته عن ليث بن أبي سليم، فقال: صاحب سنة يخرج حديثه، ثم قال أنكروا عليه الجمع بين عطاء وطاووس ومجاهد حسب(1) باب الميم","",{"fn":"(1) تهذيب التهذيب ٨/٤٦٧."}],[410,"سألته عن محمد بن إسحاق بن يسار عن أبيه، فقال لا يحتج بهما(1) وإنما يعتبر بهما.","",{"fn":"(1) خالف الدارقطني أئمة النقد في تضعيفه والد محمد- وقد ترجح للحافظ ابن حجر أنه ثقة. أما إبنه محمد بن إسحاق فهو صدوق وكلام الدارقطني يطابق هذا الوصف."}],[411,"وسألته عن محمد بن إبراهيم بن العلاء الشامي فقال: كذاب."],[412,"سمعته يقول: محمد بن أيوب بن سويد الرملي متروك. وأبوه يعتبر به."],[413,"ومحمد بن جعفر بن الزبير يروي عن عروة مدني يعتبر به(1).","",{"fn":"(1) ونقل الحافظ في تهذيب التهذيب ٩/٩٣ عن الدارقطني أنه قال مدني ثقة."}],[414,"ومحمد بن حمير عن الأوزاعي حمصي لا بأس به."],[415,"ومحمد بن الحسن بن زبالة(1) المخزومي متروك.","",{"fn":"(1) بفتح الزاي وتخفيف الموحدة تقريب التهذيب ٢٩٤."}],[416,"ومحمد بن دينار الطاحي(1) بصري متروك وقال مرة ضعيف.","",{"fn":"(1) الطاحي بمهملتين. تقريب التهذيب ٢٩٧."}],[417,"وسالت أب الحسن بن مظفر عن محمد بن دينار فقال لا بأس به(1).","",{"fn":"(1) في تهذيب التهذيب ٩/١٥٥، قال البرقاني. وسألت أبا الحسين ابن المظفر عنه..الخ."}],[418,"سمعت الدارقطني يقول: محمد بن ربيعة الكلابي يروي عنه أبو كريب ثقة."],[419,"ومحمد بن راشد المكحولي، كان بالبصرة يعتبر به. وسمعته مرة أخرى يقول: محمد بن راشد الضرير بصري يحدث عن روح بن القاسم بن عبيد ليس بالقوي، يعتبر به. وسمعته مرة أخرى يقول: محمد بن راشد الكوفي ثقة يحدث عن يحي."],[420,"وسمعته يقول: محمد بن أبي إسماعيل ومحمد بن راشد عن أبيه عن أم الدرداء، مقل لا أعرف له سندا."],[421,"ومحمد بن زيد بن مهاجرين قنفذ مدني قال مرة: يحتج به، وقال مرة أخرى: يعتبر به."],[422,"محمد بن أبي حفصة أبو سلمة، صالح بصري يعتبر به."],[423,"محمد بن سوقة(1) بن عمير هو مولى جرير بن عبد الله، كوفي فاضل ثقة. محمد بن سعيد أبو عبد الرحمن قتل في الزندقة(2) يعرف بالمصلوب يحدث عن ربيعة بن يزيد الدمشقي.","",{"fn":"(1) ابن سوقه بضم المهملة. تقريب التهذيب ٣٠٠.\n(2) قال ابو مسهر، قتله أبو جعفر في الزندقة وقد ذكر في الضعفاء رقم الترجمة ٤٥٩. ونقل الحافظ ابن حجر عن الدارقطني أنه قال فيه متروك الحديث. المجروحون ٢/٢٤٠، تهذيب التهذيب ٩/١٨٦."}],[424,"وسمعته يقول: الحميدي عن محمد بن أبي شيبة من ولد كعب بن مالك مديني أنصاري، لا بأس به مقل."],[425,"قلت له: أبو عثمان محمد بن شريك المكي من هو؟ فقال ثقة معروف يحدث عنه وكيع وأبو نعيم وغيرهما."],[426,"سألته عن محمد بن صالح يروي عنه زيد بن الحباب، فقال هو التمار همداني متروك."],[427,"قلت له: شريك عن محمد بن عبد الرحمن عن عطاء قال: يشبه أن يكون ابن أبي ليلى."],[428,"وسمعته يقول: محمد بن عبد الله بن عبيد بن عمير، يحدث عن أبيه عن جده عن النبي صلى الله عليه وسلم متروك."],[429,"ومحمد بن عبد الرحمن بن محمد بن عبد الله بن أبي سليمان العرزمي هو عم عباد بن أحمد العرزمي(1) وأبو سليمان ميسرة هو الفزاري.","",{"fn":"(1) قال الذهبي. محمد بن عبد الرحمن بن محمد العزرمي. قال الدارقطني متروك الحديث هو وأبوه وجده ميزان الاعتدال ٣/٦٢٧."}],[430,"ومحمد بن عبد الرحمن متروك وأبوه وجده."],[431,"قلت: محمد بن عبد الرحمن بن طلحة القرشي، فقال متروك ولا أدري من أين هو."],[432,"وسمعته يقول: محمد بن عبد الرحمن بن عبد الله بن الحارثة بن النعمان هوأبو الرجال(1) وأمه عمرة بنت عبد الرحمن بن أسعد بن زرارة، ويقال له سعد بن زرارة، وليس بصحيح هو ابن أخي عمرة بنت عبد الرحمن.","",{"fn":"(1) أبو الرجال بكسر الراء وتخفيف الجيم. تقريب التهذيب ٣٠٧."}],[433,"محمد بن عبد الملك الدقيقي ثقة. قلت لأبي الحسن:"],[434,"محمد بن عياش بن عمرو العامري عن الأعمش فقال: صالح عزيز الحديث حدث الثوري عن أبيه(1).","",{"fn":"(1) قال أبو حاتم- هو شيخ كوفي لا أعلم روى عنه غير عبيد الله الحنفي. الجرح ٤/١/٥١."}],[435,"قلت: محمد بن عثمان الواسطي عن ثابت البناني قال: مجهول."],[436,"قلت: محمد بن عمرو بن الخليل، قال لا أعرفه(1).","",{"fn":"(1) لسان الميزان ٥/٣٣٠."}],[437,"قلت: محمد بن عبدة بن الحكم(1) قال مروزي ثقة وأبوه ثقة.","",{"fn":"(1) الجرح والتعديل ٤/١/١٣."}],[438,"قلت: محمد بن عون مولى أم حكيم، قال مديني ثقة يحدث عن أبيه."],[439,"قلت: محمد بن الفضل بن عطية الخرساني، قال: متروك."],[440,"قلت: محمد بن القاسم بن عبد الرزاق الجمحي قاضي مكة يحدث عن جبارة، قال: صالح."],[441,"قلت محمد بن أبي كريب(1) مولى ابن عباس قال متروك.","",{"fn":"(1) في تقريب التهذيب محمد بن كريب. تقريب التهذيب ٣١٦."}],[442,"قلت: محمد بن كليب يحدث عن جابر قال: مقل يعتبر به."],[443,"قلت: محمد بن معاوية النيسابوري حدث عنه مطين وغيره، قال كان بمكة يضع الحديث متروك(1).","",{"fn":"(1) نقل الحافظ ابن حجر في تهذيب التهذيب ٩/٤٦٠، عن الدارقطني أنه قال كذاب يضع الحديث."}],[444,"قلت: محمد بن مسلم بن مهران بن المثنى قال: بصري يحدث عن جده لا بأس بهما."],[445,"قلت: محمد بن مروان القطان، قال شيخ من الشيعة حاطب ليل لا يكاد يحدث عن ثقة، متروك."],[446,"وسمعته يقول: محمد بن محصن ويقال ابن إسحاق الأندلسي والعكاشي(1) عن الثوري والأوزاعي وابن عجلان وابن أبي عبلة متروك يضع.","",{"fn":"(1) قال الحافظ، وقد وحد بعضهم بينهما- أي بين الاندلسي والعكاشي والراجح التفرقة. لسان الميزان ٥/٦٧."}],[447,"محمد بن مهاجر أخو حنيف بغدادي متروك."],[448,"وحمد بن النوار بصري ثقة."],[449,"وحمد بن الوليد بن نويفع من أهل المدينة يعتبر به."],[450,"محمد بن واسع الأزدي بصري عابد ثقة، قلت هو الذي يحدث عن سالم بن عبد الله بن عمر قال: نعم، ثم قال: إلا أنه بلي برواة عنه ضعفاء."],[451,"قلت له: محمد بن يحي بن قيس المدايني، قال يحدث عن ابن جريج ثقة، وأبوه كذلك."],[452,"قلت: محمد بن يحي بن فياض الزماني(1) يحدث عنه ابن غنام قال بصري ثقة.","",{"fn":"(1) ابن فياض بفتح الفاء وتشديد التحتانية-الزماني- بكسر الزاي وتشديد الميم تقريب التهذيب ٣٢٣."}],[453,"قلت محمد بن يوسف مولى عمرو بن عثمان عن أبيه عن معاوية، قال محمد ثقة من أهل المدينة وأبوه لا بأس به سمع من معاوية. سألت عن حديث نافع بن سليمان عن محمد بن أبي صالح عن أبيه عن عائشة \" الإمام ضامن\"."],[454,"قال: محمد هذا مجهول وقيل هو أخو سهيل يترك هذا الحديث(1).","",{"fn":"(1) قال المزي: ذكر عن علي بن الميني أنه لم يثبت حديث أبي صالح عن أبي هريرة ولا حديث أبي صالح عن عائشة في هذا. تحفة الأشراف ٩/٣٧٢."}],[455,"سألته عن محمد بن الحسن صاحب أبي حنيفة رحمه الله، فقال: قال يحي بن معين كذاب، وقال فيه أحمد يعني بن حنبل نحو هذا، قال أبو الحسن: وعندي لا يستحق الترك(1).","",{"fn":"(1) انظر لسان الميزان ٥/١٢٢."}],[456,"وسمعته يقول: محمد بن جابر وأيوب بن جابر أخوان ضعيفان متقاربان، قيل له: يتركان، قال: لا يعتبر بهما(1).","",{"fn":"(1) قال الحافظ ابن حجر في تهذيب التهذيب ٩/٩٠ قال الداقطني. هو وأخوه يتقاربان في الضعف، وقيل له يتركان فقال لا بل يعتبر بيهما."}],[457,"قلت روى هشيم عن محمد بن عبد الرحمن القرشي من هو؟ فقال شيخ."],[458,"قلت: محمد بن الحسن الهمداني عن جعفر بن محمد يروي عنه شريح بن يونس فقال: كوفي لا شيء."],[459,"سمعته يقول: شريح بن يونس عن محمد بن الحجاج اللخمي، كذاب من أهل واسط هو صاحب حديث الهريسة(1).","",{"fn":"(1) أورده الحافظ ابن حجر حديث الهريسة. في لسان الميزان ٥/١١٦-١١٧. ولا يخلوا كتاب في الموضوعات والضعفاء إلا وذكر فيه حديث الهريسة."}],[460,"ومحمد بن عثمان بن صفوان بن أمية الجمحي من أهل مكة، ليس بالقوي(1) تفرد بحديث عن هشام بن عروة في الزكاة(2).","",{"fn":"(1) في تهذيب التهذيب ٩/٣٣٧ قال الدارقطني ليس بشيء.\n(2) أورده الذهبي في الميزان ٣/٦٤١ ولفظه، ما خالطت الصدقة مالا قط إلا أهلكته."}],[461,"وسألته عن حديث لحسان بن علي عن محمد بن عبيد الله بن أبي رافع عن أبيه عن جده، قال لي: لا تخرجه هذا محمد بن عبيد الله متروك له معضلات هو من أهل الكوفة."],[462,"قلت له: روى ابن عيينة عن أبي فروة قال: هو مسلم بن سالم لا بأس به."],[463,"قلت له: أبو حمزة عن إبراهيم، قال اسمه ميمون."],[464,"وسمعته يقول: مبارك بن فضالة لين كثير الخطأ بصري يعتبر به."],[465,"ومحارب بن دثار(1) ثقة.","",{"fn":"(1) محارب بضم أوله وكسر الراء. ابن دثار بكسر المهملة وتخفيف المثلثة. تقريب التهذيب ٣٢٩."}],[466,"ومحل بن محرز (1) الضبي ثقة كوفي.","",{"fn":"(1) محل بضم أوله وكسر ثانيه وتشديد اللام. تقريب التهذيب ٣٣٠."}],[467,"ومحل بن خليفة ثقة."],[468,"ومدر أبو زياد عن عائشة مجهول(1).","",{"fn":"(1) انظر ميزان الاعتدال ٤/٨٦، لسان الميزان ٦/١٢."}],[469,"ومثنى بن بكر يحدث عن فايد أبي الورقاء بصري متروك."],[470,"ومهران بن المثنى أبو جعفر عن ابن عمر لا بأس به، حدث عنه إسماعيل بن أبي خالد."],[471,"ومجالد بن سعيد الكوفي ليس بثقة، يزيد بن أبي زياد أرجح منه، ومجالد لا يعتبر به."],[472,"ومرثد١ بن عبد الله ا(1)ليزني أبو الخير ثقة.","",{"fn":"(1) مرثد بسكون الراء بعدها مثلثة. تقريب التهذيب ٣٧١."}],[473,"ومبشر بن أبي المليح عن أبيه لا بأس به ويحتج بحديثه وأخواه زياد ومحمد يحدثان عن أبيهما أيضا يعتبر بهما."],[474,"ومهدي بن عيسى أبو الحسن الواسطي الطحان عن أبي الزناد لا بأس به."],[475,"قلت له: أبو الأحوص عن أبي فروة قال: هو مسلم بن سالم النهدي(1) كوفي لا باس به.","",{"fn":"(1) سبق وأن ترجم في رقم ٤٧٤."}],[476,"قلت ابن أبي ذئب عن مسلم الحطاب عن ابن عمر قال هو: مدني ثقة."],[477,"قلت مسلم بن الحارث التميمي عن أبيه عن النبي صلى الله عليه وسلم قال: مسلم مجهول، لا يحدث عن أبيه إلا هو(1).","",{"fn":"(1) في تهذيب التهذيب ١٠/١٢٥، لا يروي عن أبيه غيره."}],[478,"قلت: مسلم الأعور، قال متروك وقال لي مرة أخرى: مسلم بن كيسان الأعور بياع السابري، ضعيف ليس يستحق أن يترك(1).","",{"fn":"(1) وقال فيه مرة. مضبوط الحديث. تهذيب التهذيب ١/١٣٦."}],[479,"قلت: مسلم بن يسار، قال أبو عثمان الطنبذي(1) من أهل مصر لا يعتبر به.","",{"fn":"(1) الطنبذي. بضم الطاء وسكون النون وضم الباء الموحدة وفي آخرها ذال معجمة وقد أورد الحافظ ابن حجر ترجمة الرجل ونقل الدارقطني أنه قال فيه يعتب به ولعله نقله من الميزان. وقد ثبت للذهبي أنه لا يبلغ حديثه درجة الصحة وهو في نفسه صدوق. وأستغرب ما حكم به عليه في الكاشف إذ قال فيه ثقة. انظر:- اللباب ٢/٢٨٩، ميزان الاعتدال ٤/١٠٧. الكاشف ٣/١٤٣، تهذيب التهذيب ١/١٤٢."}],[480,"وسمعته يقول: مسلم بن عبيد أبو نصيرة، ليس ممن يحتج به يشبه أن يكون واسطيا(1).","",{"fn":"(1) قال الذهبي في ميزان الاعتدال ٤/٥٨. ضعفه الدارقطني في علل مسند الصديق."}],[481,"ملازم بن عمرو يمامي ثقة، أقام بالبصرة، قلت حديثه عن عبد الله بن بدر اليمامي عن قيس بن طلق عن أبيه، قال: كلهم من أهل اليمامة وهذا إسناد مجهول يخرج."],[482,"قلت حديث بن أبي سليم عن رجل عن أنس بن مالك رضي الله عنه عن النبي صلى الله عليه وسلم في \" النوم عن النوم قبل العشاء والحديث بعدها\"، قال: الرجل هو مسلم الأعور."],[483,"قلت: مالك بن نمير الخزامي عن أبيه، قال: لا يحدث عن أبيه إلا هو، يعتبر به ولا بأس بأبيه(1).","",{"fn":"(1) قال الحافظ ابن حجر:- هذا الكلام فيه نظر فإن أباه ذكر أنه رأى النبي صلى الله عليه وآله وسلم قاعدا في الصلاة فإن ثبن اسناده فهو صحابي. تهذيب التهذيب ١١/٢٣."}],[484,"قلت: مالك بن دينار، قال ثقة، ولا يكاد يحدث عنه ثقة."],[485,"قلت: مالك بن أبي الرجال قال صالح، حدث الواقدي وأبو علي الحنفي عنه، ويقول الحنفي: مالك بن محمد بن أبي الرجال(1).٣.","",{"fn":"(1) الجرح والتعديل ٤/١/٢١٦."}],[486,"قلت موسى بن وردان عن أبي هريرة، قال لا بأس به."],[487,"قلت: موسى بن ثوران، قال: ويقال بن سروان عن طلحة بن عبيد الله بن كريز عن عائشة رضي الله عنها، إسناد محمول حمله الناس(1).","",{"fn":"(1) في تهذيب التهذيب ١٠/٣٣٨. سئل عنه الدلر قطني فقال اسناد مجهول حمله الناس."}],[488,"قلت له: أبو خلف موسى بن خلف، قال بصري ليس بالقوي يعتبر به حدث عنه عثمان."],[489,"قلت موسى بن هلال الطويل عن أنس قال: متروك."],[490,"قلت موسى بن عبد الله بن يزيد بن زيد، قال: ثقة وأبوه وجده(1) صحابيان.","",{"fn":"(1) انظر أقول الائمة في صحبة عبد الله بن يزيد في الاصابة. ٢/٣٨٣."}],[491,"قلت له: موسى بن أنس بن مالك بن عمه ثمامة عن جده أنس بن مالك رضي الله عنه، قال: يخرج الحديث اعتبارا وموسى كوفي."],[492,"وسمعته يقول: موسى بن محمد أبو عمران يقال له: ابن العلي الشطوي(1) حدث عنه ببغداد ضعيف يترك.","",{"fn":"(1) الشطوي بفتح الشين المعجمة والطاء المهملة وفي آخرها واو. اللباب ٢/١٩٦."}],[493,"موسى بن نصر الرازي أبو سهل(1).","",{"fn":"(1) لسان الميزان ٦/١٣٤."}],[494,"مصعب بن المقدام ثقة."],[495,"ومصعب بن أبي ذئب عن القاسم بن محمد مني متروك."],[496,"مغيرة بن مسلم يحدث عنه مروان بن معاوية خراساني لا بأس به."],[497,"ومعين بن زياد موصلي يحدث عنه وكيع يعتبر به."],[498,"ومغيرة بن سبيع(1) عن ابن بريدة كوفي يحتج به.","",{"fn":"(1) سبيع:- بمهملة وموحدةمصغرا. تقريب التهذيب ٣٤٥."}],[499,"معضل بن إسماعيل التيمي كوفي لا بأس به."],[500,"معروف بن واصل كوفي يكنى أبا بدل(1).","",{"fn":"(1) ويقال ابو يزيد. وذكره الامام مسلم في باب أبو بدل الكنى لمسلم ١/١٨٦، تهذيب التهذيب ١٠/٢٢٩."}],[501,"مروان بن شجاع ثقة جزري."],[502,"قلت له: روى الوليد بن مسلم عن مروان بن جناح، قال: لا بأس به شامي أصله كوفي(1). في باب النون والهاء","",{"fn":"(1) تهذيب التهذيب ١٠/٩٠."}],[503,"سألته عن نهشل عن الضحاك، هو ابن مزاحم قال: نعم."],[504,"قلت: نهشل ابن من؟ قال: ابن سعيد الدارمي لا شيء."],[505,"وسألته عن عدي بن الفضل، قال: يترك، ثم قال: وأبو جزي نصر بن طريف أسو حالا منه(1).","",{"fn":"(1) في لسان الميزان ٦/١٥٥، سئل الدارقطني عن عدي بن الفضل فقال. يترك. ثم قال وابو جزى أسوأ حالا منه. ولم يتخلف أحد عن ذكره في الضعفاء ولا أعلم فيه توثيقا."}],[506,"قلت له: نابل صاحب العباء(1) عن ابن عمر هو ثقة، فأشار أن لا.","",{"fn":"(1) ويقال صاحب الشمال أيضا. تهذيب التهذيب ١٠/٣٩٧."}],[507,"وسمعته يقول: نسير بن ذعلوق(1) من أهل الكوفة ثقة.","",{"fn":"(1) نسير. بمهملة مصغرا. ابن دعلوق بضم المعجمة واللام بينهما مهملة ساكنة تقريب التهذيب ٣٥٦."}],[508,"والنضر بن طاهر. بصري مبروك."],[509,"همام عن أبي غالب. اسمه نافع. ثقة. يحدث عن أنس."],[510,"قلت. نعمان عن ابن عباس. قال مجهول يحدث عنه أبو عجلان."],[511,"وسمعته يقول. نسير بن ذغلوق (1) من أهل الكوفة ثقة.","",{"fn":"(1) نسير. بمهملة مصغرا. ابن دعلوق بضم المعجمة واللام بينهما مهملة ساكنة تقريب التهذيب ٣٥٦."}],[512,"قلت له: أبو معاذ نهار بن عثمان القناد شيخ ابن ناجية كيف هو؟ قال: شيخ بصري، لم يزدني على هذا."],[513,"قلت له: روى سريج بن يونس عن أبي الحسين هارون بن مسلم، قال صاحب الحناء، بصري صويلح يعتبر به."],[514,"وسمعته يقول: الهجنع بن قيس لا شيء وهو كوفي وله حديثان(1). باب الواو(2) باب الياء سمعت أبا الحسن يقول:","",{"fn":"(1) لسان الميزان ٦/١٩١.\n(2) لم أجد في هذا الباب ترجمة. واغلب ظني انه سقط من أصل الكتاب ولم يتنبه الناسخ إلى ذلك. وقد عدت إلى كتب التراجم التي اعتمدت على البرقاني فوجدت في تاريخ بغداد ترجمة واحدة وهي ترجمة:- وهب بن حفص اخبرنا البرقاني اخبرنا ابو الحسن الدارقطني قال:- وهب بن حفص الحراني. كان ضعيفا تاريخ بغداد ١٣/٤٥٨."}],[515,"يحي الجابر هو ابن عبد الله التيمي كوفي يعتبر به."],[516,"محبر لا يتابع على أحاديثه، ولا يكاد يروي عن شيوخه غيره."],[517,"ويحي بن عبد الله بن سالم بن عبد الله ثقة مدني حديثه بمصر."],[518,"قلت أبوه، قال: لا أعلم لأبيه حديثا."],[519,"ويحي بن عبد الرحمن الأرحبي(1) كوفي صالح يعتبر به يروي عنه أبو كريب.","",{"fn":"(1) الا رحبي. بفتح الهمزة وسكون الراء وفتح الحاء المهملة اللباب ١/٤٠."}],[520,"قلت له: يحي بن عبد الرحمن بن حاطب عن ابن عمر، قال ثقة حدث عنه عروة وهو أيضا حدث عن عروة."],[521,"قلت يحي بن عبد الملك بن حميد بن أبي غنية(1) يحدث عنه أبو بكر ابن أبي شيبة. قال: ثقة وأبوه ثقة.","",{"fn":"(1) أبي غنية- بفتح المعجمة وكسر النون وتشديد التحتانية. تقريب التهذيب ٣٧٧."}],[522,"قلت ابن دينار، قال: أبو هاشم الرماني: ثقة."],[523,"يحي بن عباد الضبعي أبو عباد، قال بغدادي يحتج به."],[524,"قلت: يحي بن عباد بن عبد الله بن الزبير عن أبيه عن معاوية، قال: سماع أبيه عن معاوية لا يصح إلا أنه أدركه، ويحي وأبوه عباد ثقتان."],[525,"قلت يحي بن سعيد بن أبان بن سعيد بن العاص الأموي، قال ثقة."],[526,"قلت يحي بن سلمة بن كهيل قال: متروك، وابنه إسماعيل بن يحي كذلك، وأخوه محمد بن سلمة بن كهيل يعتبر به."],[527,"قلت: يحي بن قيس المازني يحدث عنه البرساني، قال: ثقة من ناحية اليمن."],[528,"قلت: يحي بن المهلب قال: أبو كدينة(1) يعتبر به.","",{"fn":"(1) أبو كدينة: بنون مصغرة. تقريب التهذيب ٣٧٩."}],[529,"قلت: يحي بن معاذ الدسري، قال: يعتبر به."],[530,"وسمعته يقول: يحي بن هانئ يحدث عن أبو بكر بن عياش والثوري كوفي يحتج به."],[531,"قلت له: قتادة بن مالك، قال: هو أبو أيوب العتكي(1) مراغي. ثقة سمع من سمرة.","",{"fn":"(1) العتكي:- بفتح العين المهملة، والثاء المنقوطة بنقطتين من فوق وكسر الكاف الأنساب للسمعاني ٣٨٤أ."}],[532,"قلت يحي بن ميمون، قال ثقة قاضي مصر. سمع من سهل بن سعد حينما دخل مصر."],[533,"قلت يحي بن أبي سليم أبو بلج(1) قال: واسطي ثقة.","",{"fn":"(1) أبو بلج:- بفتح أوله وسكون اللام بعدها جيم- القزازي الكوفي. ثم الواسطي. كبير اسمه يحيى بن سليم أو ابن أبي الأسود. صدوق ربما أخطأ من الخامسة. تقريب التهذيب ٣٩٨."}],[534,"قلت حماد عن أبي المعلا العطار، قال: اسمه يحي بصري لا يعتبر به."],[535,"سألت أبا الحسن عن يزيد بن ربيعة عن أبي الأشعث قال دمشقي متروك."],[536,"وعن يزيد بن صليح(1) قال حمصي لا يعتبر به.","",{"fn":"(1) يزيد بن صالح وقيل ابن صليح ويقال ابن صبيح. وصحح المزي في الاطراف ان اسم أبيه صليح وبه جزم البخاري وابن أبي خيثمة ويعقوب بن سفيان وغير واحد. تهذيب التهذيب ١١/٣٧٣."}],[537,"وعن يزيد بن يوسف الدمشقي، فقال: متروك حمري يروي عن الأوزاعي وقال لنا مرة أخرى اختلفوا فيه فيحي بن معين يغمز عليه(1) وليس يستحق عندي الترك.","",{"fn":"(1) قال فيه ابن معين. ليس بثقة وقال مرة لا يساوي شيئا. ومرة ليس هو بشيء ونقل الحافظ ابن حجر عن الدارقطني انه قال فيه متروك. التاريخ ٢/٦٩٧، تهذيب التهذيب ١١/٣٧٣."}],[538,"وسألته عن يزيد بن زيد مولى أبي أسيد البدري فقال: مجهول(1) متروك.","",{"fn":"(1) اقتصر في اللسان على قول. مجهول. لسان الميزان ٦/٢٨٧."}],[539,"وعن يزيد بن أبي سفيان فقال: أبو المهزم بصري، أساء القول فيه شعبة، يترك."],[540,"وعن يزيد بن كميت شيخ للحسين العتاب فقال: كوفي متروك."],[541,"قلت محمد بن فضيل عن أبي إسماعيل الأسدي فقال: هو يزيد بن كهيل كوفي ثقة."],[542,"سألته عن يزيد بن عبد العزيز بن سياه فقال: كوفي ثقة."],[543,"قلت يزيد بن يعفر عن الحسن قال: بصري معروف يعتبر به."],[544,"قلت يزيد بن طلق، قال: يعنبر به."],[545,"قلت يزيد بن شريح قال: حمصي يعتبر به."],[546,"قلت يزيد بن بابنوس(1) عن عائشة قال: بصري لا بأس به.","",{"fn":"(1) بابنوس بموحدتين بينهما الف ثم نون مضمومة وواو ساكنة ومهملة. تقريب التهذيب ٣٨١."}],[547,"وسمعته يقول: يزيد بن محمد بن سنان الرهاوي هو أبو فروة وجده متروك."],[548,"وسألته عن يزيد بن أبي زياد فقال: لا يخرج عنه في الصحيح ضعيف يخطئ كثيرا (ويتلقن إذا لقن(1)) ٢.","",{"fn":"(1) في تهذيب التهذيب ١١/٣٣١ ويلقن إذا لقن."}],[549,"وسمعته يقول: يحسن(1) عن عائشة مولى ثقة بصري كنيته أبو موسى.","",{"fn":"(1) يحسن. بضم أوله وفتح المهملة وتشديد النون المفتوحة ثم مهملة. ابن عبد الله. تقريب التهذيب ٣٧٣."}],[550,"وسمعته يقول: يونس بن ميسرة بن حلبس(1) ثقة دمشقي.","",{"fn":"(1) ابن حلبس. بمهملتين في طرفيه وموحدة وزن جعفر. تقريب التهذيب ٣٩٠."}],[551,"وسألته عن يوسف بن سيف فقال: حمصي ثقة."],[552,"قلت يونس بن أبي يعفور يروي عن أبيه قال: كوفيان ثقتان."],[553,"قلت له: يعقوب بن عتبة بن المغيرة بن الأخنس قال: مديني ثقة، يروي عن عروة عن الزهري."],[554,"سألته عن أبي يوسف(1) صاحب أبي حنيفة فقال: هو أقوى من محمد بن الحسن.","",{"fn":"(1) اسمه يعقوب بن إبراهيم. اورده الخطيب في تاريخه ونقل فيه أقوال الأئمة النقاد. تاريخ بغداد ١٤/١٢٤٢."}],[555,"وسمعته يقول: يعقوب بن إسحاق أبو عمارة الرازي ثقة حدث عنه سريج بن يونس والحسن بن عرفة وعبد الحميد بن سنان."],[556,"وسألته عن يوسف بن عطية فقال: هما اثنان متروكان أحد هما بصري أبو سهل وهو الصفار يحدث عن ثابت وقتادة، والآخر كوفي كنيته أبو المنذر يحدث عن أبي حمزة مجهول(1). في الكنى وغير ذلك","",{"fn":"(1) تهذيب التهذيب ١١/٤٦٩."}],[557,"قلت لأبي الحسن: أبو أويس صاحب الزهري، قال: اسمه عبد الله بن عبد الله بن أويس بن مالك بن أبي عامر وهو بن عم مالك بن أنس(1) من أهل المدينة سماعه مع مالك عن الزهري. قلت: كيف حديثه عن الزهري قال: في بعضها شيء. سألته عن هذين الإسنادين: ملازم بن عمرو عن عبد الله بن بدر عن قيس بن طلق عن أبيه ن النبي صلى الله عليه وسلم. وعبد الله بن بدر عن عبد الرحمن بن علي عن أبيه عن بن شيبان عن النبي صلى الله عليه وسلم، حملهما الناس ويخرجان.","",{"fn":"(1) زاد في تهذيب التهذيب ٥/٢٨٠ وصهره على أخته. هكذا في الاصل ولا بد أن يكون هناك سقط ولا بد من إضافة كلمة. قال."}],[558,"قلت: علي بن شيبان صحابي، قال: نعم(1).","",{"fn":"(1) قال الحافظ ابن حجر:- كان أحد الوفد من بني حنيفة وله أحاديث اخرجها البخاري في الأدب المفرد وأبو داود وابن ماجه وابن خزيمة وابن حبان منها من طريق عبد الله بن بدر عن عبد الرحمن بن علي بن سيبان عن أبيه وكان أحد الوفد قال: خرجنا حتى قدمنا على رسول الله صلى الله عليه وآله وسلم حتى بايعناه. الاصابة ٢/٥٠٧."}],[559,"وسمعته يقول: أبو سعيد مولى بني هاشم اسمه عبد الرحمن بن عبد الله(1).","",{"fn":"(1) الكنى والاسماء ٢/٤٣٤."}],[560,"وأبو نعامة السعدي، عبد ربه بصري صالح."],[561,"الحسن وعلي ابنا صالح بن حي وهما أخوان لا ثالث لهما ثم قال وغلط ابن الجعابي فقال: صالح بن صالح هو أخوهما فوافقته فتبين (له(1)) ٣ أنه أخطأ.","",{"fn":"(1) هكذا في الأصل. ولعل الصواب. فتبين لي."}],[562,"موسى بن وردان كان بمصر."],[563,"وعبد الرحمن بن وردان أبو بكر الغفاري مدني صالح يحدث عن أنس."],[564,"وسلمة بن وردان مدني ليس بينهم قرابة(1).","",{"fn":"(1) تقدم في باب عبد الرحمن رقم الترجمة ٢٧١."}],[565,"أبو حمزة الذي يقول شعبة جارنا اسمه عبد الرحمن بن أبي عبد الله."],[566,"وحدث هشيم عن أبي حمزة الأسدي قال شهدت ابن عباس، وهو آخر وهو أيضا واسطي ليس بالقوي."],[567,"وذكر له وأنا أسمع حديث السواك الذي رواه أبو الصقيل، فقال: أبو علي لا بأس به(1) ثم قال في الحديث اضطراب فيه منه.","",{"fn":"(1) ميزان الاعتدال ٤/٥٥٤."}],[568,"وسمعته يقول: الجريري عن أبي الورد شيخ له، ما حدث عنه غيره(1).","",{"fn":"(1) في تهذيب التهذيب ١٢/٢٧٢، قال الدارقطني ما حدث عنه غيره كذا قال. وقد حدث عنه أيضا شداد بن سعيد أبو طلحة الراسبي. وقال في تقريب التهذيب ٤٣٢، مقبول من السادسة."}],[569,"وسألته عن حديث الدراوردي عن محمد بن عثمان بن عبد الرحمن بن سعيد بن يربوع عن جده فقال: محمد مديني ثقة، وجده تابعي وسعيد بن يربوع له صحبة يكنى أبا هود. أخو عبد الله وعبيد الله وأبي بكر بني عمر هم أربعة."],[570,"فأما عاصم فضعيف قريب من عبد الله."],[571,"وأبو بكر بن عمر قليل الحديث بمرة ثقة. وقد تكلم أبو عبد الرحمن النسائي على أحمد بن صالح حيث قال أربعتهم ثقات."],[572,"أم موسى عن علي حديثها مستقيم، فقال هي سرية لعلي(1) يخرج حديثها اعتبارا. وقلت له: حديث هشام بن زياد عن محمد بن كعب القرظي عن ابن عباس الحديث الطويل الذي فيه ذكر عمر بن عبد العزيز، فقل: أفسده عفان لأنه قال حدثنيه هشام قديما عن فلان عن محمد بن كعب ذكره اسمه الدارقطني فنسيته أنا، قال: فلما كان بعد، حدث به عن محمد بن كعب، قال أبو الحسن وبودي أن يكون صحيحا فإنه عندنا عالي، حدثنا به عبيد الله العيشي عن هشام قلت ابن منيع، قال: نعم. سمعته يقول:","",{"fn":"(1) قيل اسمها فاختة وقيل حبيبة. مقبولة من الثالثة. تقريب التهذيب ٤٧٧."}],[573,"أبو يزيد الملائي عن ابن عمر مجهول."],[574,"أبو مريم الثقفي عن عمار مجهول متروك(1).","",{"fn":"(1) تهذيب التهذيب ١٢/٢٣٢."}],[575,"وأبو سفيان ٢ عن أبي هريرة(1)، هو مولى أبي أحمد بن جحش ثقة مديني.","",{"fn":"(1) قال الدارقطني. اسمه وهبة. وقال غيره اسنه قزمان. وقال ابن عبد البر لا يصح له اسم غير كنيته. تهذيب التهذيب ١٢/١١٣."}],[576,"وأبو مدرك متروك."],[577,"وأبو ثمامة الحناط ويقال القماح لا يعرف يترك."],[578,"وأبو سعيد بن عوذ عن مجاهد يحدث عنه أبو أحمد الزبيري لا يعرف اسمه(1) مكي يعتبر به، سمع من ابن الزبير النهدي عن الحسين بن علي، مجهول.","",{"fn":"(1) قال الذهبي. اسمه رجاء بن الحارث ضعف. ميزان الاعتدال ٢/٤٦/٤/٥٣٠."}],[579,"وقتادة عن أبي مراية بصري لم يحدث عنه غيره، يعتبر به."],[580,"وقتادة عن أبي ميمونة عن أبي هريرة مجهول يترك(1).","",{"fn":"(1) تهذيب التهذيب ١٢/٢٥٣."}],[581,"وأبو إسماعيل العبدي عن أنس متروك بصري."],[582,"وأبو رملة عن معاوية شامي مجهول يترك."],[583,"وأبو بكر بن أبي مريم قيل اسمه بكير حمصي متروك(1).","",{"fn":"(1) قال الحافظ ابن حجر:- أبو بكر بن عبد الله بن أبي مريم العسائي الشامي وقد ينسب إلى جده. قيل اسنه بكير وقيل عبد السلام. ضعيف. وكان قد سرق بيته فاختلط من السابعة. تقريب التهذيب ٣٩٦."}],[584,"وأبو أمامة عن الأسود بن يزيد يحدث عنه محمد بن سوقة مجهول."],[585,"وأبو عبد الله عن يحي بن أبي كثير مجهول لا يعرف."],[586,"وأبو سعد الساعدي عن أنس مجهول يترك حديثه."],[587,"وأبو ماجد وقيل أبو ماجدة عن ابن مسعود مجهول متروك."],[588,"وأبو أحمد الزبيري عن أبي شعبة الطحان لا أعرف أبا شعبة مجهول."],[589,"أبو إسماعيل عن أبي حنظلة عن ابن عمر هو ابن أبي خالد، وأبو حنظلة لا يعرف اسمه ولا بأس به(1).","",{"fn":"(1) قال الحافظ ابن حجر- لا أعرف فيه جرحا بل ذكر ابن خلفون في الثقات قلت:- أورده الإمام مسلم في الكنى وقال. أبو حنظلة الحذاء. الكنى١/٣٣٢، تعجيل المنفعة ٣١٥."}],[590,"المسعودي عن أبي عمرو وقيل أبي عمر دمشقي متروك."],[591,"وأبو زياد مولى آل دراج عن أبي بكر لا يعرف يترك."],[592,"وأبو عذبة٢ عن نافع مجهو(1)ل، يروي حديث الغسل.","",{"fn":"(1) قال الذهبي. أبو عذبة. بالحركات. ميزان الاعتدال ٤/٥٥١."}],[593,"وأبو شعبة الطحان جار الأعمش لا يعرف اسمه كوفي، متروك."],[594,"وأبو عتبة الكندي عن أبي أمامة، حمصي يخرج حديثه اعتبارا لا يعرف اسمه."],[595,"ابن معانق أو أبو معانق عن أبي مالك الأشعري لا شيء مجهول."],[596,"وابن لاس الخزاعي مجهول لا يعرف ويقال أبو لاس."],[597,"وأبو عبد الرحمن المعافري مجهول."],[598,"وأبو حفصة مولى عائشة مجهول(1) لا أعلم حدث به عنه غير يحي بن أبي كثير فيخرج حديث الكسوف، إذا حسن طريقه إلى يحي.","",{"fn":"(1) نقل الحافظ ابن حجر عن الدارقطني أنه قال. مجهول يكتب حديثه. تهذيب التهذيب ١٢/٧٦."}],[599,"وأبو نصير الواسطي متروك لا أعرف اسمه يحدث عنه سويد بن عبد العزيز."],[600,"وأبو حريز مولى معاوية لا شيء مجهول وقيل أبو جرير."],[601,"أبو رافع الصائغ عن أبي هريرة، قيل اسمه نفيع(1) ولا يصح، هو بصري ثقة.","",{"fn":"(1) قال ابن حجر قال الدارقطني قيل. إن اسمه نفيع ولا يصح يعني أن اسمه قتيبة. تهذيب التهذيب ١٠/٤٧٢."}],[602,"وسألته عن أبي الخطاب عن أبي سعيد الخدري فقال: مجهول."],[603,"وعن يعلى بن عطاء عن أبي علقمة عن أبي هريرة، فقال: أبو علقمة لا يعرف اسمه، ولا من هو ولكن يخرج هذا الحديث اعتبارا. حدث الأئمة عن يعلى."],[604,"وسمعته يقول: أبو مزاحم عن أبي هريرة لا يعرف يترك."],[605,"وأبو الربيع عن ابن عمر مجهول لا يحدث عنه إلا أبو سعيد الطحان(1).","",{"fn":"(1) في ميزان الاعتدال ٤٠/٥٢٣. أبو الربيع عن ابن عمر. وعنه أبو شعبة الطحان قال الدارقطني مجهول ولأبي شعبة الطحان ترجمة في ميزان الاعتدال ٤/٥٣٦."}],[606,"وأبو بكر بن أبي موسى عن أبي موسى الأشعري، واسم أبي بكر هذا عمرو."],[607,"وأبو بكر بن أبي إياس، لا أعرفه."],[608,"وسمعته يقول: ابن عيينة أصله كوفي، أقام بمكة، وكان أبوه يحج به قديما. آخر السؤالات والحمد لله وحده وصلواته على سيدنا محمد وآله وصحبه وسلم، وحسبنا الله تعالى ونعم الوكيل."],[609,"أسئلة البرذعي لأبي زرعة الرازي. تحقيق د/ سعد هاشمي- ط المجلس العلمي- بالجامعة الإسلامية."],[610,"التاريخ لابن معين- رواية الدوري. تحقيق د/ أحمد محمد نور سيف- ط الأولى عام ١٣٩٩هـ."],[611,"تاريخ بغداد للخطيب البغدادي (ت ٤٦٣هـ) . ط الأولى عام ١٣٤٩هـ بمطبعة السعادة."],[612,"تاريخ التراث العربي- فؤاد سزكين. ترجمة د/ محمود فهمي حجازي، ود/ فهمي أبو الفضل. ط الثانية عام ١٩٧٧م- الهيئة المصرية العامة."],[613,"تاريخ جرجان- للحافظ السهمي (ت ٤٢٧هـ) . تصحيح المعلمي -ط بمطبعة مجلس دائرة المعارف العثمانية حيدر أباد١٣٥٠هـ."],[614,"التاريخ الكبير للإمام البخاري (ت٢٥٦هـ) . ط الأولى١٣٦١هـ بمطبعة دائرة المعارف العثمانية."],[615,"تحفة الأحوذي للمباركفوري. مراجعة عبد الوهاب عبد اللطيف، نشر محمد عبد المحسن الكتبي ط مطبعة المدني الطبعة الثانية."],[616,"تحفة الأشراف للحافظ جمال الدين المزي (ت٧٤٢هـ) . تصحيح وتعليق عبد الصمد شرف الدين. نشر الدار القيمة. ط الأولى."],[617,"التحفة اللطيفة للسخاوي (ت٩٠٢هـ) . تحقيق أسعد طرابزوني- ط مطبعة السنة المحمدية."],[618,"تذكرة الحفاظ للذهبي (ت٧٤٨هـ) . ط- مطبعة مجلس دائرة المعارف العثمانية. ط الثالثة عام ١٣٧٧هـ."],[619,"تقريب التهذيب للحافظ ابن حجر العسقلاني (ت٨٥٢هـ) . دار نشر الكتب الإسلامية –كوجر انوالة-باكستان- ط الأولى عام١٣٩٣هـ."],[620,"تهذيب التهذيب لابن حجر العسقلاني. ط بمطبعة دائرة المعارف النظامية. ط الأولى."],[621,"تهذيب الكمال للمزي. مخطوط مصور في مكتبة الجامعة الإسلامية."],[622,"الجرح والتعديل(1): لابن أبي حاتم (ت٣٢٧هـ) . تحقيق عبد الرحمن المعلمي- ط بمطبعة مجلس دائرة المعارف. ط الأولى عام ١٣٧١هـ.","",{"fn":"(1) من الذين سألهم السهمي، ابا محمد العنبري، أبا زرعة الجرجانيومحمد بن أحمد ابن سفيان وغيرهم. إلا أنه لم يكثر الشؤالات ... وإطلاق اسم السؤالات عن الدارقطني لهذا الكتاب له وجه. إذ أن معظم الأسئلة وجهت إلى الدارقطني."}],[623,"الخلاصة لصفي الدين الخزرجي (ت٩٢٣هـ) . نشر مكتبة المطبوعات الإسلامية. حلب- ط الثانية عام١٣٩١هـ."],[624,"سنن ابن ماجه: للحافظ أبي عبد الله بن ماجه (ت٢٧٥هـ) . تحقيق محمد فؤاد عبد الباقي. ط دار احياء الكتب العربية عام١٣٧٢هـ."],[625,"سنن النسائي: بشرح السيوطي وحاشية السندي. ط دار إحياء التراث العربي. بيروت-لبنان."],[626,"سؤالات أبي عبيد الآجري(1). رسالة ماجستير. تحقيق محمد علي قاسم العمري. بإشراف د/ محمود أحمد ميرة.","",{"fn":"(1) قام الأستاذ محمد قاسم العمري بتحقيق جزء ٣ لنيل شهادة الماجستير."}],[627,"سؤالات الحافظ السلفي لخميس الحوزي. تحقيق مطاع الطرابيشي. دمشق- مجمع اللغة العربية."],[628,"سؤالات الحاكم للدار قطني. نسخة مصورة في الجامعة الإسلامية تحت رقم (١٨١٨) مجموع."],[629,"سؤالات السلمي للدار قطني. نسخة مصورة في الجامعة الإسلامية تحت رقم (١٨١٨) مجموع."],[630,"الضعفاء والمتروكين للدار قطني. نسخة مصورة في الجامعة الإسلامية تحت رقم (١٨١٨) مجموع."],[631,"طبقات الفقهاد للشيرازي. تحقيق إحسان عباس. ط دائرة الرائد العربي. بيروت."],[632,"العلل ومعرفة الرجال: للإمام أحمد ابن حنبل (ت٢٤١هـ) . تحقيق د/ طلعت قوج، ود/ إسماعيل جراح. أنقرة١٩٦٣م."],[633,"الكاشف: للإمام الذهبي. تحقيق عزت علي عطية، وموسى محمد علي الموشى. ط الأولى ١٣٩٢هـ. ط دار النصر."],[634,"الكامل: لابن عدي. نسخة مصورة في مكتبة الدراسات العليا تحت رقم ١١٤/١١٥."],[635,"الكنى: لأبي أحمد الحاكم. نسخة مصورة في الجامعة الإسلامية. بدون رقم."],[636,"اللباب: لعز الدين ابن الأثير. ط دار صادر."],[637,"لسان الميزان: للحافظ ابن حجر العسقلاني (٨٥٢هـ) . نشر مؤسسة الأعلمي للمطبوعات."],[638,"مختصر سنن أبي داود: للمنذري. تحقيق أحمد محمد شاكر، ومحمد حامد الفقي. ط مطبعة السنة المحمدية."],[639,"المعجم المفهرس. النسخة المصورة من المكتبة الأزهرية- وهي في قسم المخطوطات تحت رقم (١٧١٩ مكبر) ."],[640,"المغني في ضبط أسماء الرجال: للفتى (ت٩٨٦هـ) . ط دار الكتاب العربي. بيروت، عام ١٣٩٩هـ."],[641,"ميزان الاعتدال: للإمام الذهبي (ت٩٤٨هـ) . تحقيق علي محمد البجاوي. ط دار إحياء الكتاب العربي."]])